"""Contrastive transition selection helpers for world-model induction."""

import random
import re
from typing import Dict, List, Tuple

from patchworld.worldmodel_data import Trajectory, Transition


def _action_type(action: str) -> str:
    """Reduce an action to its type/template by stripping specific values."""
    action = action.strip().lower()
    if not action:
        return ""

    # Wordle actions often appear as spaced letters: "s h i r e".
    if re.fullmatch(r"[a-z](?:\s+[a-z]){4}", action):
        return "<5-letter-guess>"

    # API-style actions like search[foo], click[bar], guess[a b c d e].
    bracket_match = re.fullmatch(r"([a-z_][a-z0-9_ ]*)\[(.*)\]", action)
    if bracket_match:
        name = bracket_match.group(1).strip()
        payload = bracket_match.group(2).strip()
        if name == "click":
            if re.fullmatch(r"[a-z0-9]{10}", payload, flags=re.IGNORECASE):
                return "click[<asin>]"
            if payload.lower().startswith("page "):
                return "click[page]"
            if payload in {"next >", "< prev", "back to search", "search", "buy now"}:
                return f"click[{payload.lower()}]"
            return "click[<option>]"
        if name == "search":
            return "search[<query>]"
        if name == "guess":
            return "guess[<5-letter-word>]"
        return f"{name}[<X>]"

    # Standard text actions.
    tokens = action.split()
    if len(tokens) == 1:
        return tokens[0]
    if tokens[0] in {"go", "pick", "put", "turn", "look"} and len(tokens) >= 2:
        verb = " ".join(tokens[:2])
    else:
        verb = tokens[0]
    return verb + " <X>"


def _outcome_type(next_obs: str) -> str:
    """Reduce a next_observation to its outcome type."""
    lo = next_obs.strip().lower()
    if not lo:
        return "EMPTY"
    if re.fullmatch(r"[byg](?: [byg]){4}", lo):
        return "WORDLE_FEEDBACK"
    if lo == "invalid word":
        return "WORDLE_INVALID"
    if "welcome to the game of wordle" in lo:
        return "WORDLE_WELCOME"
    if lo.startswith("webshop [sep] ") or lo.startswith("instruction: [sep] "):
        if "price:" in lo and "rating:" in lo:
            return "WEBSHOP_PRODUCT_PAGE"
        if any(k in lo for k in ("size [sep]", "color [sep]", "fit type [sep]", "flavor [sep]", "item shape [sep]", "scent [sep]")):
            return "WEBSHOP_FILTER_PAGE"
        if "page " in lo or "back to search" in lo:
            return "WEBSHOP_RESULTS_PAGE"
    # Known failure patterns
    if any(f in lo for f in ["no known action", "nothing happens", "invalid", "i can't", "you can't"]):
        return "FAIL"
    # Truncate and normalise to first ~40 chars as a signature
    return re.sub(r"[^a-z ]", " ", lo[:60]).strip()


def _task_text_from_observation(obs_text: str) -> str:
    match = re.search(
        r"Task description:\s*Your task is to ([^\n]+)",
        obs_text or "",
        flags=re.IGNORECASE,
    )
    if not match:
        return ""
    return match.group(1).strip().rstrip(".")


def _sciworld_task_family(obs_text: str) -> str:
    task = _task_text_from_observation(obs_text).lower()
    if not task:
        return "other"
    if "electrically conductive" in task:
        return "conductivity"
    if "measure the temperature" in task:
        return "temperature"
    if "measure the melting point" in task:
        return "melting_point"
    if task.startswith(("melt ", "boil ", "freeze ")) or "change the state of matter" in task:
        return "state_change"
    if "use chemistry to create" in task:
        return "chemistry"
    if "light bulb" in task or "powering it using" in task:
        return "circuits"
    if "focus on the" in task and "life stage" in task:
        return "life_cycle"
    if "longest life span" in task or "shortest life span" in task:
        return "lifespan"
    if "find a(n)" in task:
        return "classification"
    return "other"


def _alfworld_task_family(obs_text: str) -> str:
    task = _task_text_from_observation(obs_text).lower()
    if not task:
        return "other"
    if "clean" in task:
        return "clean"
    if "heat" in task:
        return "heat"
    if "cool" in task:
        return "cool"
    if "put " in task and (" in " in task or " on " in task):
        return "put"
    if any(tok in task for tok in ("pick", "take", "find", "get ")):
        return "pickup"
    return _normalize_signature(task, max_len=72)


def _normalize_signature(text: str, *, max_len: int = 160) -> str:
    return re.sub(r"\s+", " ", (text or "").strip().lower())[:max_len]


def _wordle_guess_key(action: str) -> str:
    return re.sub(r"[^a-z]", "", (action or "").lower())


def _webshop_bucket(obs_or_next_obs: str) -> str:
    outcome = _outcome_type(obs_or_next_obs)
    if outcome.startswith("WEBSHOP_"):
        return outcome
    lo = (obs_or_next_obs or "").lower()
    if "your score (min 0.0, max 1.0)" in lo or "buy now" in lo:
        return "WEBSHOP_CHECKOUT_PAGE"
    return outcome


def _is_move_action(action: str) -> bool:
    action = (action or "").strip().lower()
    return action in {"north", "south", "east", "west", "up", "down"} or action.startswith(
        ("move ", "go ")
    )


def _maze_coord_signature(obs_text: str) -> str:
    text = obs_text or ""
    matches = re.findall(r"position\s*(-?\d+)\s*,\s*(-?\d+)", text, flags=re.IGNORECASE)
    if not matches:
        return "pos:unknown"
    x, y = matches[-1]
    return f"pos:{x},{y}"


def _maze_wall_signature(obs_text: str) -> str:
    lo = (obs_text or "").lower()
    walls: List[str] = []
    if "above you" in lo:
        walls.append("up")
    if "below you" in lo:
        walls.append("down")
    if "to your left" in lo:
        walls.append("left")
    if "to your right" in lo:
        walls.append("right")
    if not walls:
        return "walls:none"
    ordered = [direction for direction in ("up", "down", "left", "right") if direction in walls]
    return "walls:" + ",".join(ordered)


def deduplicate_transitions(
    trajectories: List[Trajectory],
    max_per_pattern: int = 2,
) -> List[Tuple[Transition, str, str]]:
    """Extract one representative transition per (action_type, outcome_type) pair.

    Returns list of (transition, action_type, outcome_type).
    Scales to large trajectory sets: N trajectories → K unique patterns.
    """
    seen: Dict[Tuple[str, str], int] = {}
    result: List[Tuple[Transition, str, str]] = []

    for traj in trajectories:
        for step in traj.transitions:
            at = _action_type(step.action)
            ot = _outcome_type(step.next_observation)
            key = (at, ot)
            count = seen.get(key, 0)
            if count < max_per_pattern:
                result.append((step, at, ot))
                seen[key] = count + 1

    return result


# ---------------------------------------------------------------------------
# Contrastive example selection
# ---------------------------------------------------------------------------

def select_contrastive_examples(
    trajectories: List[Trajectory],
    max_transitions: int = 30,
    max_per_pattern: int = 2,
) -> List[Transition]:
    """Select transitions that maximise action-type coverage and outcome diversity.

    For each action type, include at least one success and one failure transition
    so the LLM sees the same action producing different outputs — forcing it to
    learn the parametric rule rather than a specific mapping.
    """
    deduped = deduplicate_transitions(trajectories, max_per_pattern=max_per_pattern)
    # Group by action_type
    by_action: Dict[str, List[Tuple[Transition, str, str]]] = {}
    for step, at, ot in deduped:
        by_action.setdefault(at, []).append((step, at, ot))

    selected: List[Transition] = []
    # Round-robin across action types to keep diversity
    action_types = sorted(by_action.keys(), key=lambda at: (-len(by_action[at]), at))
    i = 0
    while len(selected) < max_transitions and i < len(action_types) * max_transitions:
        at = action_types[i % len(action_types)]
        pool = by_action[at]
        if pool:
            step, _, _ = pool.pop(0)
            selected.append(step)
        i += 1

    return selected[:max_transitions]


def select_random_examples(
    trajectories: List[Trajectory],
    max_transitions: int = 30,
) -> List[Transition]:
    """Uniform random transition sampling (ablation helper)."""
    pool: List[Transition] = []
    for traj in trajectories:
        pool.extend(traj.transitions)
    if len(pool) <= max_transitions:
        return pool
    random.shuffle(pool)
    return pool[:max_transitions]


def _babyai_state_bucket(text: str) -> str:
    lo = (text or "").lower()
    tags: List[str] = []
    if "carrying" in lo:
        tags.append("carrying")
    if "key" in lo:
        tags.append("key")
    if "door" in lo:
        if "locked" in lo:
            tags.append("door_locked")
        elif "open" in lo:
            tags.append("door_open")
        else:
            tags.append("door")
    if "goal" in lo or "mission" in lo:
        tags.append("goal")
    if "picked up" in lo or "pickup" in lo:
        tags.append("pickup")
    if "drop" in lo:
        tags.append("drop")
    if not tags:
        tags.append(_outcome_type(text))
    return "+".join(tags[:3])

"""Train-only episodic residual memory for executable world models.

The wrapper keeps the generated symbolic model as the primary dynamics model.
It only overrides readout when the current observation/action pair matches a
high-confidence transition observed in the training trajectories.
"""

from __future__ import annotations

from collections import Counter
import re
from typing import Any, Dict, Iterable, List, Optional, Tuple

from patchworld.worldmodel_data import Trajectory


def _normalize_text(text: Any) -> str:
    return " ".join(str(text or "").strip().lower().split())


def _transition_key(observation: str, action: str) -> Tuple[str, str]:
    return (_normalize_text(observation), _normalize_text(action))


def _split_webshop_sections(observation: str) -> List[str]:
    return [part.strip() for part in str(observation or "").split("[SEP]") if part.strip()]


def _join_webshop_sections(parts: Iterable[str]) -> str:
    return " [SEP] ".join(str(part).strip() for part in parts if str(part).strip())


def _webshop_instruction(parts: List[str]) -> str:
    for idx, part in enumerate(parts):
        if part.lower() == "instruction:" and idx + 1 < len(parts):
            return parts[idx + 1]
    return ""


def _webshop_product_from_parts(parts: List[str], asin: str) -> Dict[str, str]:
    asin_upper = asin.strip().upper()
    for idx, part in enumerate(parts):
        if part.strip().upper() != asin_upper:
            continue
        product = {"asin": asin_upper, "title": "", "price": ""}
        if idx + 1 < len(parts):
            product["title"] = parts[idx + 1]
        for candidate in parts[idx + 2 : idx + 5]:
            if candidate.startswith("$") or candidate.lower().startswith("price:"):
                product["price"] = candidate.replace("Price:", "").strip()
                break
        return product
    return {"asin": asin_upper, "title": "", "price": ""}


def _webshop_current_asin(parts: List[str]) -> str:
    for part in parts:
        token = part.strip().upper()
        if re.fullmatch(r"B0[A-Z0-9]{8}", token):
            return token
    return ""


def _webshop_page_number(parts: List[str]) -> int:
    for part in parts:
        match = re.search(r"\bPage\s+(\d+)\b", part, flags=re.IGNORECASE)
        if match:
            return int(match.group(1))
    return 1


def _webshop_heuristic_next_observation(observation: str, action: str) -> Optional[str]:
    """Action-conditioned WebShop fallback for unseen observation/action keys.

    It intentionally preserves concrete text already visible in the current page
    and only changes structural fields that WebShop actions determine locally.
    """
    parts = _split_webshop_sections(observation)
    if not parts:
        return None
    instruction = _webshop_instruction(parts)
    action_text = str(action or "").strip()
    action_lower = action_text.lower()

    if action_lower.startswith("search[") or action_lower == "click[search]":
        return _join_webshop_sections(
            ["Instruction:", instruction, "Back to Search", "Page 1", "Next >"]
        )

    if action_lower == "click[back to search]":
        return _join_webshop_sections(["WebShop", "Instruction:", instruction, "Search"])

    if action_lower == "click[next >]" or action_lower == "next":
        page = _webshop_page_number(parts) + 1
        updated: List[str] = []
        replaced = False
        for part in parts:
            if re.search(r"\bPage\s+\d+\b", part, flags=re.IGNORECASE):
                updated.append(re.sub(r"\bPage\s+\d+\b", f"Page {page}", part, flags=re.IGNORECASE))
                replaced = True
            else:
                updated.append(part)
        if not replaced:
            updated.extend(["< Prev", f"Page {page}", "Next >"])
        elif "< Prev" not in updated:
            page_idx = next(
                (
                    idx
                    for idx, part in enumerate(updated)
                    if re.search(r"\bPage\s+\d+\b", part, flags=re.IGNORECASE)
                ),
                0,
            )
            updated.insert(page_idx, "< Prev")
        return _join_webshop_sections(updated)

    if action_lower == "click[< prev]" or action_lower == "back":
        if any(part.lower() in {"description", "features", "reviews", "buy now"} for part in parts):
            return observation
        page = max(1, _webshop_page_number(parts) - 1)
        updated = []
        for part in parts:
            if re.search(r"\bPage\s+\d+\b", part, flags=re.IGNORECASE):
                updated.append(re.sub(r"\bPage\s+\d+\b", f"Page {page}", part, flags=re.IGNORECASE))
            elif page == 1 and part == "< Prev":
                continue
            else:
                updated.append(part)
        return _join_webshop_sections(updated)

    asin_match = re.fullmatch(r"click\[(b0[a-z0-9]{8})\]", action_lower)
    if asin_match:
        asin = asin_match.group(1).upper()
        product = _webshop_product_from_parts(parts, asin)
        rendered = ["Instruction:", instruction, "Back to Search", "< Prev", asin]
        if product.get("title"):
            rendered.append(product["title"])
        if product.get("price"):
            rendered.append(f"Price: {product['price']}")
        rendered.extend(["Description", "Features", "Reviews", "Buy Now"])
        return _join_webshop_sections(rendered)

    if action_lower in {"click[description]", "click[features]", "click[reviews]"}:
        return observation

    if action_lower == "click[buy now]":
        asin = _webshop_current_asin(parts)
        return _join_webshop_sections(
            [
                "Thank you for shopping with us!",
                "Your code:",
                "None",
                "(Paste it in your MTurk interface.)",
                "Purchased",
                "asin",
                asin or "None",
                "options",
                "{}",
                "Reward",
                "Your score (min 0.0, max 1.0)",
                "1.0",
            ]
        )

    if action_lower.startswith("click["):
        # Filter/option clicks usually keep the user on a concrete product or
        # option page. Preserve current page text rather than hallucinating.
        return observation

    return None


class EpisodicResidualWorldModel:
    """Semi-parametric wrapper: symbolic dynamics plus train-only residuals.

    The memory stores empirical next-observation residuals keyed by normalized
    current observation and action. Conflicting keys are used only when the most
    common target clears ``min_confidence``.
    """

    def __init__(
        self,
        base_model: Any,
        train_trajectories: Iterable[Trajectory],
        *,
        env_name: str = "",
        max_entries: int = 0,
        min_count: int = 1,
        min_confidence: float = 1.0,
    ) -> None:
        self.base_model = base_model
        self.env_name = env_name
        self.max_entries = max(0, int(max_entries or 0))
        self.min_count = max(1, int(min_count or 1))
        self.min_confidence = min(1.0, max(0.0, float(min_confidence)))
        self._memory: Dict[Tuple[str, str], str] = {}
        self._memory_confidence: Dict[Tuple[str, str], float] = {}
        self._last_obs_by_belief_id: Dict[int, str] = {}
        self._residual_by_prior_id: Dict[int, str] = {}
        self._stats = self._build_memory(list(train_trajectories))

    @property
    def residual_stats(self) -> Dict[str, Any]:
        return dict(self._stats)

    def _build_memory(self, trajectories: List[Trajectory]) -> Dict[str, Any]:
        buckets: Dict[Tuple[str, str], Counter[str]] = {}
        total_transitions = 0
        for traj in trajectories:
            for step in traj.transitions:
                total_transitions += 1
                key = _transition_key(step.observation, step.action)
                buckets.setdefault(key, Counter())[step.next_observation] += 1

        candidates: List[Tuple[int, Tuple[str, str], str, float, int]] = []
        conflict_keys = 0
        for key, counter in buckets.items():
            total_for_key = sum(counter.values())
            if len(counter) > 1:
                conflict_keys += 1
            next_obs, count = counter.most_common(1)[0]
            confidence = count / float(total_for_key or 1)
            if count >= self.min_count and confidence >= self.min_confidence:
                candidates.append((count, key, next_obs, confidence, total_for_key))

        candidates.sort(key=lambda item: (-item[0], -item[3], item[1]))
        if self.max_entries > 0:
            candidates = candidates[: self.max_entries]

        for _count, key, next_obs, confidence, _total_for_key in candidates:
            self._memory[key] = next_obs
            self._memory_confidence[key] = confidence

        return {
            "env": self.env_name,
            "train_trajectories": len(trajectories),
            "train_transitions": total_transitions,
            "raw_keys": len(buckets),
            "conflict_keys": conflict_keys,
            "entries": len(self._memory),
            "max_entries": self.max_entries,
            "min_count": self.min_count,
            "min_confidence": self.min_confidence,
            "key": "normalized_observation_action",
        }

    def _lookup(self, observation: Optional[str], action: str) -> Optional[str]:
        if not observation:
            return None
        return self._memory.get(_transition_key(observation, action))

    def __getattr__(self, name: str) -> Any:
        return getattr(self.base_model, name)

    def init_belief(self) -> Any:
        return self.base_model.init_belief()

    def init_belief_from_observation(self, obs_text: str) -> Any:
        if hasattr(self.base_model, "init_belief_from_observation"):
            belief = self.base_model.init_belief_from_observation(obs_text)
        else:
            belief = self.base_model.init_belief()
            corrected = self.base_model.correct_belief(belief, obs_text)
            belief = belief if corrected is None else corrected
        self._last_obs_by_belief_id[id(belief)] = obs_text
        return belief

    def parse_observation(self, obs_text: str) -> Any:
        return self.base_model.parse_observation(obs_text)

    def correct_belief(self, belief_prior: Any, obs_text: str) -> Any:
        corrected = self.base_model.correct_belief(belief_prior, obs_text)
        belief = belief_prior if corrected is None else corrected
        self._last_obs_by_belief_id[id(belief)] = obs_text
        return belief

    def predict_belief(self, belief: Any, action: str) -> Any:
        current_obs = self._last_obs_by_belief_id.get(id(belief))
        residual_obs = self._lookup(current_obs, action)
        if residual_obs is None and self.env_name == "webshop" and current_obs:
            residual_obs = _webshop_heuristic_next_observation(current_obs, action)
        try:
            prior = self.base_model.predict_belief(belief, action)
        except Exception:
            prior = belief
        if residual_obs is not None:
            self._residual_by_prior_id[id(prior)] = residual_obs
        return prior

    def readout_observation(self, belief: Any, action: str = "") -> str:
        residual_obs = self._residual_by_prior_id.pop(id(belief), None)
        if residual_obs is not None:
            return residual_obs
        return self.base_model.readout_observation(belief, action) or ""

    def predict_observation(self, belief: Any, action: str) -> str:
        prior = self.predict_belief(belief, action)
        return self.readout_observation(prior, action)

    def transition(self, belief: Any, action: str) -> Any:
        return self.predict_belief(belief, action)

    def predict_next(self, state: Any, action: str) -> Any:
        return self.predict_belief(state, action)

from dataclasses import dataclass, field
import re
from typing import Any, Dict, Iterable, List, Optional, Set, Tuple


@dataclass
class GraphState:
    """Belief state for spatial environments (navigation, manipulation).

    nodes: entity_id -> attribute dict (e.g. {"type": "room", "visited": True})
    edges: set of (src_id, relation, dst_id) triples — supports both .add() and iteration
    metadata: task-level info (goal, inventory, agent_location, etc.)
    """

    nodes: Dict[str, Dict] = field(default_factory=dict)
    edges: Set[Tuple[str, str, str]] = field(default_factory=set)
    metadata: Dict = field(default_factory=dict)


@dataclass(frozen=True)
class BeliefHypothesis:
    """A weighted latent-world hypothesis maintained under partial observability."""

    hypothesis_id: str
    description: str = ""
    weight: float = 1.0
    payload: Dict[str, Any] = field(default_factory=dict)


MAZE_DIRECTIONS: Tuple[str, ...] = ("up", "down", "left", "right")


@dataclass(frozen=True)
class MazeState:
    """Canonical explicit state for maze-style navigation tasks."""

    agent_x: Optional[int] = None
    agent_y: Optional[int] = None
    goal_x: Optional[int] = None
    goal_y: Optional[int] = None
    local_walls: Tuple[str, ...] = ()
    status: str = ""
    obs_text: str = ""

    def to_dict(self) -> Dict[str, Any]:
        data: Dict[str, Any] = {
            "agent_x": self.agent_x,
            "agent_y": self.agent_y,
            "goal_x": self.goal_x,
            "goal_y": self.goal_y,
            "local_walls": self.local_walls,
        }
        if self.status:
            data["status"] = self.status
        if self.obs_text:
            data["obs_text"] = self.obs_text
        return data


def _maze_wall_direction(value: Any) -> Optional[str]:
    if isinstance(value, str):
        direction = value.strip().lower()
        aliases = {
            "above": "up",
            "above you": "up",
            "up": "up",
            "below": "down",
            "below you": "down",
            "down": "down",
            "left": "left",
            "to your left": "left",
            "right": "right",
            "to your right": "right",
        }
        return aliases.get(direction)
    if isinstance(value, tuple) and value:
        tail = value[-1]
        if isinstance(tail, str):
            return _maze_wall_direction(tail)
    return None


def canonicalize_maze_walls(value: Any) -> Tuple[str, ...]:
    walls: Set[str] = set()
    if isinstance(value, dict):
        iterable = value.keys()
    elif isinstance(value, (list, tuple, set, frozenset)):
        iterable = value
    elif value is None:
        iterable = ()
    else:
        iterable = (value,)
    for item in iterable:
        direction = _maze_wall_direction(item)
        if direction in MAZE_DIRECTIONS:
            walls.add(direction)
    return tuple(direction for direction in MAZE_DIRECTIONS if direction in walls)


def coerce_maze_state(value: Any) -> Optional[MazeState]:
    """Best-effort conversion from parsed dicts or predictions to MazeState."""
    if isinstance(value, MazeState):
        return value
    if not isinstance(value, dict):
        return None

    status = str(value.get("status", "") or "").strip().lower()
    if status == "success":
        return MazeState(status="success", obs_text=str(value.get("obs_text", "") or ""))

    if str(value.get("raw_text", "") or "").strip() == "Success":
        return MazeState(status="success", obs_text="Success")

    keys = set(value.keys())
    if not ({"agent_x", "agent_y"} & keys):
        return None

    def _as_int(name: str) -> Optional[int]:
        raw = value.get(name)
        if raw is None:
            return None
        try:
            return int(raw)
        except (TypeError, ValueError):
            return None

    return MazeState(
        agent_x=_as_int("agent_x"),
        agent_y=_as_int("agent_y"),
        goal_x=_as_int("goal_x"),
        goal_y=_as_int("goal_y"),
        local_walls=canonicalize_maze_walls(value.get("local_walls", value.get("walls"))),
        status=status,
        obs_text=str(value.get("obs_text", "") or value.get("raw_text", "") or ""),
    )


def render_maze_observation(state: MazeState) -> str:
    """Render the canonical maze state back into the environment's text format."""
    if state.status == "success":
        return "Success"
    if None in (state.agent_x, state.agent_y, state.goal_x, state.goal_y):
        return state.obs_text or ""
    base = (
        f"The goal is at position {state.goal_x}, {state.goal_y}. "
        f"Your current position is at position {state.agent_x}, {state.agent_y}."
    )
    if not state.local_walls:
        return base
    wall_text = {
        "up": "above you",
        "down": "below you",
        "left": "to your left",
        "right": "to your right",
    }
    rendered_walls = [wall_text[direction] for direction in state.local_walls]
    if len(rendered_walls) == 1:
        return f"{base} There is a wall {rendered_walls[0]}."
    if len(rendered_walls) == 2:
        joined = ", ".join(rendered_walls)
    else:
        joined = ", ".join(rendered_walls[:-1]) + f", {rendered_walls[-1]}"
    return f"{base} There are walls {joined}."


@dataclass(frozen=True)
class WordleState:
    guess_history: Tuple[str, ...] = ()
    feedback_history: Tuple[str, ...] = ()
    current_feedback: Tuple[str, ...] = ()
    candidate_count: Optional[int] = None
    status: str = ""


@dataclass(frozen=True)
class TextcraftState:
    inventory: Tuple[Tuple[str, int], ...] = ()
    goal_item: Optional[str] = None
    last_action_outcome: str = ""
    recipe_count: Optional[int] = None


@dataclass(frozen=True)
class WebshopState:
    page_type: str = ""
    current_page_number: Optional[int] = None
    selected_filters: Tuple[Tuple[str, str], ...] = ()
    asin: str = ""
    goal_completed: bool = False


def _normalize_wordle_guess(value: Any) -> Optional[str]:
    if not isinstance(value, str):
        return None
    guess = " ".join(value.strip().lower().split())
    if re.fullmatch(r"[a-z](?: [a-z]){4}", guess):
        return guess
    compact = "".join(ch for ch in guess if ch.isalpha())
    if len(compact) == 5:
        return " ".join(compact)
    return None


def _normalize_wordle_feedback(value: Any) -> Optional[Tuple[str, ...]]:
    if isinstance(value, (list, tuple)):
        items = tuple(str(item).strip().lower() for item in value)
        if len(items) == 5 and all(item in {"b", "y", "g"} for item in items):
            return items
    if not isinstance(value, str):
        return None
    feedback = " ".join(value.strip().lower().split())
    if re.fullmatch(r"[byg](?: [byg]){4}", feedback):
        return tuple(feedback.split(" "))
    return None


def _normalize_mapping_items(mapping: Any) -> Tuple[Tuple[str, Any], ...]:
    if not isinstance(mapping, dict):
        return ()
    normalized: List[Tuple[str, Any]] = []
    for key, value in sorted(mapping.items(), key=lambda item: str(item[0]).strip().lower()):
        normalized.append((str(key).strip().lower(), value))
    return tuple(normalized)


def _webshop_sections(value: Dict[str, Any]) -> Tuple[str, ...]:
    raw_sections = value.get("sections")
    if isinstance(raw_sections, (list, tuple)):
        return tuple(str(section).strip() for section in raw_sections if str(section).strip())
    raw_text = str(
        value.get("raw_observation", "")
        or value.get("obs_text", "")
        or value.get("raw_text", "")
        or ""
    )
    if not raw_text:
        return ()
    return tuple(section.strip() for section in raw_text.split("[SEP]") if section.strip())


def _infer_webshop_page_type(value: Dict[str, Any], sections: Tuple[str, ...]) -> str:
    raw_page_type = str(
        value.get("page_type", "")
        or value.get("type", "")
        or value.get("page", "")
        or ""
    ).strip().lower()
    aliases = {
        "search_page": "search",
        "search": "search",
        "results_page": "results",
        "search_results": "results",
        "results": "results",
        "product_page": "product",
        "product_detail": "product",
        "product": "product",
        "filter_options": "filter_options",
        "purchase_complete": "purchase_complete",
        "thank_you": "purchase_complete",
    }
    if raw_page_type in aliases:
        return aliases[raw_page_type]

    section_set = {section.lower() for section in sections}
    if any("thank you for shopping with us" in section for section in section_set):
        return "purchase_complete"
    if "webshop" in section_set and "search" in section_set and "back to search" not in section_set:
        return "search"
    if {"description", "features", "reviews"} & section_set or "buy now" in section_set:
        return "product"
    if "back to search" in section_set or any(section.startswith("page ") for section in section_set):
        return "results"
    return raw_page_type


def _infer_webshop_page_number(value: Dict[str, Any], sections: Tuple[str, ...]) -> Optional[int]:
    raw_page = value.get("current_page_number", value.get("page_number"))
    if raw_page is not None:
        try:
            return int(raw_page)
        except (TypeError, ValueError):
            pass
    for section in sections:
        match = re.search(r"\bPage\s+(\d+)\b", section, flags=re.IGNORECASE)
        if match:
            return int(match.group(1))
    return None


def _infer_webshop_asin(value: Dict[str, Any], sections: Tuple[str, ...], page_type: str = "") -> str:
    for raw in (
        value.get("asin"),
        value.get("active_asin"),
        value.get("purchased_item"),
        value.get("purchased_asin"),
    ):
        token = str(raw or "").strip().upper()
        if re.fullmatch(r"B0[A-Z0-9]{8}", token):
            return token
    product_details = value.get("product_details")
    if isinstance(product_details, dict):
        token = str(product_details.get("asin", "") or "").strip().upper()
        if re.fullmatch(r"B0[A-Z0-9]{8}", token):
            return token
    cart = value.get("cart", {})
    if isinstance(cart, dict):
        token = str(cart.get("asin", "") or "").strip().upper()
        if re.fullmatch(r"B0[A-Z0-9]{8}", token):
            return token
    if page_type not in {"product", "purchase_complete"}:
        return ""
    page_content = value.get("page_content", ())
    if isinstance(page_content, (list, tuple)):
        for item in page_content:
            token = str(item).strip().upper()
            if re.fullmatch(r"B0[A-Z0-9]{8}", token):
                return token
    for section in sections:
        token = section.strip().upper()
        if re.fullmatch(r"B0[A-Z0-9]{8}", token):
            return token
    return ""


def coerce_wordle_state(value: Any) -> Optional[WordleState]:
    if not isinstance(value, dict):
        return None
    guess_history_raw = value.get("guess_history", ())
    if isinstance(guess_history_raw, set):
        guess_history_iter: Iterable[Any] = sorted(guess_history_raw)
    elif isinstance(guess_history_raw, (list, tuple)):
        guess_history_iter = guess_history_raw
    else:
        guess_history_iter = ()
    guess_history = tuple(
        guess
        for guess in (_normalize_wordle_guess(item) for item in guess_history_iter)
        if guess is not None
    )

    feedback_history_raw = value.get("feedback_history", ())
    if isinstance(feedback_history_raw, set):
        feedback_history_iter: Iterable[Any] = sorted(feedback_history_raw)
    elif isinstance(feedback_history_raw, (list, tuple)):
        feedback_history_iter = feedback_history_raw
    else:
        feedback_history_iter = ()
    feedback_history = tuple(
        " ".join(feedback)
        for feedback in (_normalize_wordle_feedback(item) for item in feedback_history_iter)
        if feedback is not None
    )

    current_feedback = _normalize_wordle_feedback(
        value.get("feedback_letters")
        or value.get("current_feedback")
        or value.get("raw_text")
    ) or ()

    candidate_words = value.get("possible_words", value.get("candidate_words"))
    candidate_count: Optional[int] = None
    if isinstance(candidate_words, (set, list, tuple)):
        candidate_count = len(candidate_words)
    elif isinstance(candidate_words, dict):
        candidate_count = len(candidate_words.keys())

    status = ""
    if value.get("is_solved") is True or current_feedback == ("g", "g", "g", "g", "g"):
        status = "solved"
    elif value.get("is_invalid") is True or str(value.get("raw_text", "")).strip().lower() == "invalid word":
        status = "invalid"
    elif value.get("is_welcome") is True:
        status = "welcome"
    elif current_feedback:
        status = "feedback"

    if not any((guess_history, feedback_history, current_feedback, candidate_count is not None, status)):
        return None
    return WordleState(
        guess_history=guess_history,
        feedback_history=feedback_history,
        current_feedback=current_feedback,
        candidate_count=candidate_count,
        status=status,
    )


def coerce_textcraft_state(value: Any) -> Optional[TextcraftState]:
    if not isinstance(value, dict):
        return None
    inventory_raw = value.get("inventory", {})
    inventory: Tuple[Tuple[str, int], ...] = ()
    if isinstance(inventory_raw, dict):
        normalized_items: List[Tuple[str, int]] = []
        for key, raw_count in sorted(inventory_raw.items(), key=lambda item: str(item[0]).strip().lower()):
            try:
                count = int(raw_count)
            except (TypeError, ValueError):
                continue
            normalized_items.append((str(key).strip().lower(), count))
        inventory = tuple(normalized_items)
    goal_item = value.get("goal_item")
    if goal_item is not None:
        goal_item = str(goal_item).strip().lower() or None
    last_action_outcome = str(value.get("last_action_outcome", "") or "").strip().lower()
    crafting_recipes = value.get("crafting_recipes")
    recipe_count = len(crafting_recipes) if isinstance(crafting_recipes, (list, tuple, set)) else None
    if not any((inventory, goal_item, last_action_outcome, recipe_count is not None)):
        return None
    return TextcraftState(
        inventory=inventory,
        goal_item=goal_item,
        last_action_outcome=last_action_outcome,
        recipe_count=recipe_count,
    )


def coerce_webshop_state(value: Any) -> Optional[WebshopState]:
    if not isinstance(value, dict):
        return None
    sections = _webshop_sections(value)
    page_type = _infer_webshop_page_type(value, sections)
    current_page_number = _infer_webshop_page_number(value, sections)
    selected_filters = _normalize_mapping_items(value.get("selected_filters"))
    asin = _infer_webshop_asin(value, sections, page_type)
    goal_completed = bool(value.get("goal_completed", False) or page_type == "purchase_complete")
    if not any((page_type, current_page_number is not None, selected_filters, asin, goal_completed)):
        return None
    return WebshopState(
        page_type=page_type,
        current_page_number=current_page_number,
        selected_filters=tuple((key, str(val).strip().lower()) for key, val in selected_filters),
        asin=asin,
        goal_completed=goal_completed,
    )


class BaseWorldModel:
    """Interface that all generated world models must implement.

    This stays intentionally lightweight so that LLM-generated models can
    reasonably implement it in one pass.

    IMPORTANT: in most benchmark environments the observation is only partial
    evidence about the real world. A good model should therefore maintain a
    belief state over hidden variables, not treat the observation text as the
    full environment state.

    Spatial environments (alfworld, sciworld, babyai, maze, textcraft) should
    typically use GraphState or a structured dict as their belief state.
    API-style environments (webshop, webarena) can use a plain dict.
    """

    def parse_observation(self, obs_text: str) -> Dict:
        """Extract structured evidence from observation text.

        The parsed dict does not need to be the full latent environment state.
        It should capture directly observed constraints/signals that
        `correct_belief()` can use to maintain a richer hidden-state belief.
        """
        raise NotImplementedError

    def extract_valid_action_forms(self) -> Dict[str, List[str]]:
        """Return known action templates learned from trajectories."""
        raise NotImplementedError

    def init_belief(self) -> Any:
        """Return an empty belief state.

        Spatial models should return GraphState(); API models can return {}.
        """
        return {}

    def init_belief_from_observation(self, obs_text: str) -> Any:
        """Initialize belief directly from the first observation.

        This is a convenience wrapper for explicit predict/correct loops:
          b1 = init_belief_from_observation(o1)
        """
        belief = self.init_belief()
        return self.correct_belief(belief, obs_text)

    def predict_belief(self, belief: Any, action: str) -> Any:
        """Predict prior belief after applying action (no observation correction).

        Canonical predict step:
          b_next_prior = f(belief, action)
        """
        raise NotImplementedError

    def correct_belief(self, belief_prior: Any, obs_text: str) -> Any:
        """Correct prior belief using actual observation evidence.

        Canonical correction step:
          b_next = g(b_next_prior, obs_text)
        """
        raise NotImplementedError

    def readout_observation(self, belief: Any, action: str = "") -> str:
        """Render observation text implied by current belief.

        This is the canonical readout function used after predict/correct steps:
          o_hat = readout_observation(belief)
        """
        raise NotImplementedError

    # Backward-compatible wrappers for downstream callers.
    def transition(self, belief: Any, action: str) -> Any:
        return self.predict_belief(belief, action)

    def predict_next(self, state: Dict, action: str) -> Dict:
        return self.predict_belief(state, action)

    def predict_observation(self, belief: Any, action: str) -> str:
        belief_next_prior = self.predict_belief(belief, action)
        return self.readout_observation(belief_next_prior, action)


def _iter_belief_mappings(belief: Any) -> Iterable[Dict[str, Any]]:
    if isinstance(belief, dict):
        yield belief
        for value in belief.values():
            yield from _iter_belief_mappings(value)
        return
    if isinstance(belief, (list, tuple, set, frozenset)):
        for item in belief:
            yield from _iter_belief_mappings(item)
        return
    metadata = getattr(belief, "metadata", None)
    if isinstance(metadata, dict):
        yield metadata
        for value in metadata.values():
            yield from _iter_belief_mappings(value)
    fields = getattr(belief, "__dict__", None)
    if isinstance(fields, dict):
        yield fields
        for value in fields.values():
            yield from _iter_belief_mappings(value)


def belief_diagnostics(belief: Any) -> Dict[str, Any]:
    """Return a lightweight summary of whether belief tracks hidden-state hypotheses."""
    diagnostics = {
        "candidate_count": 0,
        "hypothesis_count": 0,
        "latent_signal_count": 0,
        "resolved_status_count": 0,
        "tracks_latent_state": False,
        "signals": [],
    }
    latent_keys = {
        "possible_words",
        "candidate_words",
        "candidate_set",
        "candidate_probs",
        "candidate_probabilities",
        "hypotheses",
        "weighted_hypotheses",
        "belief_state",
        "belief_distribution",
        "unknown_objects",
        "unseen_locations",
        "unopened_containers",
        "unexamined_entities",
        "hidden_state",
        "selected_filters",
        "latents",
        "latent_variables",
        "frontier",
        "facts",
        "epistemic_facts",
        "epistemic_status",
        "posterior",
        "probabilities",
        "weights",
        "object_location_beliefs",
        "location_beliefs",
        "container_content_beliefs",
        "content_priors",
    }
    seen_mapping_ids: Set[int] = set()
    for mapping in _iter_belief_mappings(belief):
        mapping_id = id(mapping)
        if mapping_id in seen_mapping_ids:
            continue
        seen_mapping_ids.add(mapping_id)
        for key in latent_keys:
            if key not in mapping:
                continue
            value = mapping[key]
            diagnostics["signals"].append(key)
            diagnostics["latent_signal_count"] += 1
            diagnostics["tracks_latent_state"] = True
            if isinstance(value, (set, list, tuple, dict)):
                diagnostics["candidate_count"] += len(value)
            elif hasattr(value, "__dict__"):
                diagnostics["candidate_count"] += 1
            if key == "epistemic_status" and isinstance(value, dict):
                for status in value.values():
                    raw_status = getattr(status, "value", status)
                    if not isinstance(raw_status, str):
                        continue
                    normalized = raw_status.strip().lower()
                    if normalized and normalized not in {"unknown", "unobserved", "default", "none"}:
                        diagnostics["resolved_status_count"] += 1
        hypotheses = mapping.get("hypotheses")
        if isinstance(hypotheses, (list, tuple, set)):
            diagnostics["hypothesis_count"] += len(hypotheses)
            if hypotheses:
                diagnostics["tracks_latent_state"] = True
        elif isinstance(hypotheses, dict):
            diagnostics["hypothesis_count"] += len(hypotheses)
            if hypotheses:
                diagnostics["tracks_latent_state"] = True
    diagnostics["signals"] = sorted(set(diagnostics["signals"]))
    return diagnostics


def belief_supports_latent_inference(belief: Any, env_name: str = "") -> bool:
    """Heuristic check for whether a belief carries hidden-state support."""
    diagnostics = belief_diagnostics(belief)
    if diagnostics["tracks_latent_state"]:
        return True
    env = (env_name or "").strip().lower()
    if env == "maze":
        return True
    return False

import json
from dataclasses import dataclass
from pathlib import Path
from collections import defaultdict
from typing import Dict, List, Iterable


@dataclass
class Transition:
    observation: str
    action: str
    next_observation: str
    reward: float
    done: bool


@dataclass
class Trajectory:
    transitions: List[Transition]
    env: str
    item_id: str
    task_idx: int
    rollout_index: int
    split: str
    success: bool
    total_reward: float

    @property
    def task_description(self) -> str:
        return self.transitions[0].observation if self.transitions else ""

    @property
    def num_steps(self) -> int:
        return len(self.transitions)


def _load_trajectories_from_file(jsonl_path: Path) -> List[Trajectory]:
    trajectories: List[Trajectory] = []
    with jsonl_path.open("r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            data = json.loads(line)
            meta = data.get("metadata", {})
            transitions_data = data.get("transitions", [])
            transitions = [
                Transition(
                    observation=t.get("observation", ""),
                    action=t.get("action", ""),
                    next_observation=t.get("next_observation", ""),
                    reward=float(t.get("reward", 0.0)),
                    done=bool(t.get("done", False)),
                )
                for t in transitions_data
            ]
            if not meta:
                # Fallback to minimal metadata when older formats are used.
                meta = {
                    "env": data.get("environment", ""),
                    "item_id": "",
                    "task_idx": -1,
                    "rollout_index": 0,
                    "split": "train",
                    "success": False,
                    "total_reward": sum(t.reward for t in transitions),
                }

            trajectories.append(
                Trajectory(
                    transitions=transitions,
                    env=str(meta.get("env", "")),
                    item_id=str(meta.get("item_id", "")),
                    task_idx=int(meta.get("task_idx", -1)),
                    rollout_index=int(meta.get("rollout_index", 0)),
                    split=str(meta.get("split", "train")),
                    success=bool(meta.get("success", False)),
                    total_reward=float(meta.get("total_reward", 0.0)),
                )
            )
    return trajectories


def load_trajectories(paths: Iterable[Path]) -> List[Trajectory]:
    """Load trajectories from one or more JSONL files."""
    all_trajs: List[Trajectory] = []
    for p in paths:
        if not p.exists():
            continue
        all_trajs.extend(_load_trajectories_from_file(p))
    return all_trajs


def group_by_problem(trajectories: List[Trajectory]) -> Dict[str, List[Trajectory]]:
    groups: Dict[str, List[Trajectory]] = defaultdict(list)
    for traj in trajectories:
        if traj.item_id:
            groups[traj.item_id].append(traj)
    for item_id in groups:
        groups[item_id].sort(key=lambda t: t.rollout_index)
    return dict(groups)


def group_by_task_type(trajectories: List[Trajectory]) -> Dict[str, List[Trajectory]]:
    groups: Dict[str, List[Trajectory]] = defaultdict(list)
    for traj in trajectories:
        desc = traj.task_description.split(".")[0].strip().lower()
        groups[desc].append(traj)
    return dict(groups)


def get_stats(trajectories: List[Trajectory]) -> Dict:
    problems = group_by_problem(trajectories)
    task_types = group_by_task_type(trajectories)
    n = len(trajectories)
    success_rate = (
        float(sum(1 for t in trajectories if t.success)) / float(n) if n > 0 else 0.0
    )
    return {
        "total_trajectories": n,
        "total_problems": len(problems),
        "task_types": len(task_types),
        "success_rate": success_rate,
        "task_type_samples": {k: len(v) for k, v in task_types.items()},
    }

"""Evaluation metrics for induced world models.

Two primary metrics:
  - experience_fit:   how well the model replays *known* trajectories
                      (parse + transition/prediction consistency)
  - observation_fit:  how well the model predicts *unseen* next observations
                      (token-F1 between predicted and actual next obs text)

Use evaluate_world_model() as the main entry point.
"""

