def _token_f1(predicted: str, actual: str) -> float:
    """Compute unigram token overlap F1 between two strings."""
    pred_tokens = set(predicted.lower().split())
    actual_tokens = set(actual.lower().split())
    if not pred_tokens or not actual_tokens:
        return 0.0
    common = pred_tokens & actual_tokens
    if not common:
        return 0.0
    precision = len(common) / len(pred_tokens)
    recall = len(common) / len(actual_tokens)
    return 2 * precision * recall / (precision + recall)


def _safe_bleu4(predicted: str, actual: str) -> float:
    """Sentence BLEU-4 with smoothing; returns 0 on unavailable deps/errors."""
    if not sentence_bleu or not SmoothingFunction:
        return 0.0
    pred_tokens = predicted.split()
    ref_tokens = actual.split()
    if not pred_tokens or not ref_tokens:
        return 0.0
    try:
        smoothing = SmoothingFunction().method1
        return float(
            sentence_bleu(
                [ref_tokens],
                pred_tokens,
                weights=(0.25, 0.25, 0.25, 0.25),
                smoothing_function=smoothing,
            )
        )
    except Exception:
        return 0.0


def _is_non_error_prediction(predicted_obs: str) -> bool:
    """Coverage counts non-empty and non-error-like predictions only."""
    if not predicted_obs or not predicted_obs.strip():
        return False
    lo = predicted_obs.lower()
    return not any(marker in lo for marker in ("traceback", "exception", "error:"))


def _infer_env_name(model: Any) -> str:
    cls_name = getattr(getattr(model, "__class__", None), "__name__", "") or ""
    lowered = cls_name.lower()
    for env_name in ("alfworld", "babyai", "maze", "sciworld", "textcraft", "webshop", "wordle"):
        if env_name in lowered:
            return env_name
    return ""


def _init_belief_from_first_observation(model: Any, first_obs: str) -> Any:
    belief = model.init_belief()
    corrected = model.correct_belief(belief, first_obs)
    return belief if corrected is None else corrected


def _predict_belief_prior(model: Any, belief: Any, action: str) -> Any:
    return model.predict_belief(belief, action)


def _readout_observation_from_belief(model: Any, belief: Any, action: str) -> str:
    return model.readout_observation(belief, action) or ""


def _correct_belief_with_observation(model: Any, belief_prior: Any, obs_text: str) -> Any:
    corrected = model.correct_belief(belief_prior, obs_text)
    return belief_prior if corrected is None else corrected


def _is_placeholder_prediction(predicted_obs: str, env_name: str = "") -> bool:
    text = (predicted_obs or "").strip().lower()
    if not text:
        return False
    generic_patterns = (
        "<asin>",
        "<title>",
        "<price>",
        "<rating>",
        "<filter_options>",
        "<product_details>",
        "<results_list>",
        "<description_content>",
        "<features_content>",
        "<reviews_content>",
        "[room_name]",
        "action effect not modeled.",
        "no known action matches that input",
        "sample product",
        "placeholder",
    )
    if any(pattern in text for pattern in generic_patterns):
        return True

    env = (env_name or "").strip().lower()
    if env == "webshop" and text.count("[sep]") >= 4 and re.search(r"<[^>]+>", text):
        return True
    if env in {"alfworld", "sciworld", "textcraft"} and text == "nothing happens.":
        return True
    if env == "textcraft" and "could not find enough items to craft item" in text:
        return True
    return False


def _canonical_key(key: Any) -> str:
    return str(key).strip().lower()


def _normalize_scalar(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, str):
        return " ".join(value.strip().lower().split())
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value
    return str(value).strip().lower()


def _normalize_value(value: Any, _seen: Optional[set[int]] = None) -> Any:
    if _seen is None:
        _seen = set()

    is_container = isinstance(value, (dict, set, frozenset, list, tuple))
    obj_id = id(value)
    if is_container:
        if obj_id in _seen:
            # Prevent infinite recursion on self-referential beliefs/parsed structures.
            return "<cycle>"
        _seen.add(obj_id)

    try:
        if isinstance(value, dict):
            return {
                _canonical_key(k): _normalize_value(v, _seen)
                for k, v in sorted(value.items(), key=lambda item: _canonical_key(item[0]))
            }
        if isinstance(value, (set, frozenset, list, tuple)):
            normalized_items = [_normalize_value(item, _seen) for item in value]
            return tuple(sorted(normalized_items, key=lambda item: repr(item)))
        return _normalize_scalar(value)
    finally:
        if is_container:
            _seen.remove(obj_id)


def _first_present(parsed: Dict[str, Any], keys: Iterable[str]) -> Tuple[bool, Any]:
    for key in keys:
        if key in parsed:
            return True, _normalize_value(parsed[key])
        lowered = key.lower()
        for candidate, value in parsed.items():
            if _canonical_key(candidate) == lowered:
                return True, _normalize_value(value)
    return False, None


def extract_observation_state_fields(parsed: Dict[str, Any]) -> Dict[str, Any]:
    """Extract canonical observation fields used for state-level scoring."""
    if not isinstance(parsed, dict):
        return {}
    fields: Dict[str, Any] = {}
    for field_name, aliases in STATE_FIELD_ALIASES.items():
        present, value = _first_present(parsed, aliases)
        if present:
            fields[field_name] = value
    return fields


def normalize_parsed_observation(parsed: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(parsed, dict):
        return {}
    return {
        _canonical_key(key): _normalize_value(value)
        for key, value in sorted(parsed.items(), key=lambda item: _canonical_key(item[0]))
    }


def extract_maze_state_fields(parsed: Dict[str, Any]) -> Dict[str, Any]:
    maze_state = coerce_maze_state(parsed)
    if maze_state is None:
        return {}
    fields: Dict[str, Any] = {}
    if maze_state.agent_x is not None and maze_state.agent_y is not None:
        fields["agent_position"] = (maze_state.agent_x, maze_state.agent_y)
    if maze_state.goal_x is not None and maze_state.goal_y is not None:
        fields["goal_position"] = (maze_state.goal_x, maze_state.goal_y)
    if maze_state.local_walls or "local_walls" in parsed or "walls" in parsed:
        fields["wall_set"] = maze_state.local_walls
    if maze_state.status:
        fields["terminal_status"] = maze_state.status
    return fields


def extract_wordle_state_fields(parsed: Dict[str, Any]) -> Dict[str, Any]:
    wordle_state = coerce_wordle_state(parsed)
    if wordle_state is None:
        return {}
    fields: Dict[str, Any] = {}
    if wordle_state.current_feedback:
        fields["wordle_feedback"] = wordle_state.current_feedback
    if wordle_state.status:
        fields["wordle_status"] = wordle_state.status
    if wordle_state.candidate_count is not None:
        fields["wordle_candidate_count"] = wordle_state.candidate_count
    return fields


def extract_textcraft_state_fields(parsed: Dict[str, Any]) -> Dict[str, Any]:
    textcraft_state = coerce_textcraft_state(parsed)
    if textcraft_state is None:
        return {}
    fields: Dict[str, Any] = {}
    if textcraft_state.inventory:
        fields["textcraft_inventory"] = textcraft_state.inventory
    if textcraft_state.goal_item:
        fields["textcraft_goal_item"] = textcraft_state.goal_item
    if textcraft_state.last_action_outcome:
        fields["textcraft_last_action"] = textcraft_state.last_action_outcome
    if textcraft_state.recipe_count is not None:
        fields["textcraft_recipe_count"] = textcraft_state.recipe_count
    return fields


def extract_webshop_state_fields(parsed: Dict[str, Any]) -> Dict[str, Any]:
    webshop_state = coerce_webshop_state(parsed)
    if webshop_state is None:
        return {}
    fields: Dict[str, Any] = {}
    if webshop_state.page_type:
        fields["webshop_page_type"] = webshop_state.page_type
    if webshop_state.current_page_number is not None:
        fields["webshop_page_number"] = webshop_state.current_page_number
    if webshop_state.selected_filters:
        fields["webshop_filters"] = webshop_state.selected_filters
    if webshop_state.asin:
        fields["webshop_asin"] = webshop_state.asin
    fields["webshop_goal_completed"] = webshop_state.goal_completed
    return fields


def compare_parsed_observations(
    predicted: Dict[str, Any],
    actual: Dict[str, Any],
) -> Dict[str, Any]:
    """Compare parsed predicted and gold observations at state level."""
    pred_norm = normalize_parsed_observation(predicted)
    actual_norm = normalize_parsed_observation(actual)
    pred_specialized_fields: Dict[str, Any] = {}
    actual_specialized_fields: Dict[str, Any] = {}
    for extractor in (
        extract_maze_state_fields,
        extract_wordle_state_fields,
        extract_textcraft_state_fields,
        extract_webshop_state_fields,
    ):
        pred_specialized_fields.update(extractor(predicted))
        actual_specialized_fields.update(extractor(actual))
    pred_fields = extract_observation_state_fields(pred_norm)
    actual_fields = extract_observation_state_fields(actual_norm)
    if pred_specialized_fields or actual_specialized_fields:
        pred_fields = {**pred_fields, **pred_specialized_fields}
        actual_fields = {**actual_fields, **actual_specialized_fields}
        field_matches: Dict[str, Optional[bool]] = {}
        compared_fields = 0
        matched_fields = 0
        ordered_fields = ("room", "objects", "inventory") + SPECIALIZED_FIELD_NAMES
        for field_name in ordered_fields:
            pred_has = field_name in pred_fields
            actual_has = field_name in actual_fields
            if not pred_has and not actual_has:
                field_matches[field_name] = None
                continue
            compared_fields += 1
            match = pred_fields.get(field_name) == actual_fields.get(field_name)
            field_matches[field_name] = match
            if match:
                matched_fields += 1
        return {
            "state_match": matched_fields == compared_fields if compared_fields > 0 else False,
            "field_matches": field_matches,
            "compared_fields": compared_fields,
            "field_match_fraction": (matched_fields / compared_fields if compared_fields > 0 else 0.0),
            "predicted_fields": pred_fields,
            "actual_fields": actual_fields,
        }

    field_matches: Dict[str, Optional[bool]] = {}
    compared_fields = 0
    matched_fields = 0
    for field_name in ("room", "objects", "inventory"):
        pred_has = field_name in pred_fields
        actual_has = field_name in actual_fields
        if not pred_has and not actual_has:
            field_matches[field_name] = None
            continue
        compared_fields += 1
        match = pred_fields.get(field_name) == actual_fields.get(field_name)
        field_matches[field_name] = match
        if match:
            matched_fields += 1

    if compared_fields == 0:
        full_state_match = pred_norm == actual_norm
        field_matches["full_state"] = full_state_match
        compared_fields = 1
        matched_fields = 1 if full_state_match else 0

    return {
        "state_match": matched_fields == compared_fields,
        "field_matches": field_matches,
        "compared_fields": compared_fields,
        "field_match_fraction": (matched_fields / compared_fields if compared_fields > 0 else 0.0),
        "predicted_fields": pred_fields,
        "actual_fields": actual_fields,
    }


def compute_experience_fit(model: Any, trajectories: List[Trajectory]) -> Dict:
    """Measure how accurately the model replays known trajectories.

    Returns:
        parse_success_rate        – fraction of obs parsed without exception
        predict_success_rate      – fraction of transitions predicted without exception
        overall                   – mean of parse/predict rates
    """
    parse_total = parse_ok = 0
    predict_total = predict_ok = 0
    latent_belief_total = latent_belief_ok = 0

    for traj in trajectories:
        if not traj.transitions:
            continue
        belief = _init_belief_from_first_observation(model, traj.transitions[0].observation)
        state: Dict = {}
        env_name = (getattr(traj, "env", "") or "").strip().lower()

        for step in traj.transitions:
            next_parsed: Dict[str, Any] = {}
            # Parse observation — succeed if either parse_observation OR correction works
            parse_total += 1
            parse_succeeded = False
            try:
                parsed = model.parse_observation(step.observation)
                if isinstance(parsed, dict):
                    state.update(parsed)
                parse_succeeded = True
            except NotImplementedError:
                pass
            except Exception:
                pass
            try:
                belief = _correct_belief_with_observation(model, belief, step.observation)
                parse_succeeded = True
            except Exception:
                pass
            if env_name and env_name != "maze":
                latent_belief_total += 1
                if belief_supports_latent_inference(belief, env_name):
                    latent_belief_ok += 1
            if parse_succeeded:
                parse_ok += 1

            try:
                parsed_next_candidate = model.parse_observation(step.next_observation)
                if isinstance(parsed_next_candidate, dict):
                    next_parsed = parsed_next_candidate
            except Exception:
                next_parsed = {}

            current_maze = coerce_maze_state(state)
            next_maze = coerce_maze_state(next_parsed)
            is_maze_transition = current_maze is not None or next_maze is not None

            # Predict — succeed if either predict_next OR predict_observation works
            predict_total += 1
            predict_succeeded = False
            predicted_state: Any = None
            try:
                predicted_state = model.predict_belief(belief, step.action)
                predict_succeeded = True
            except NotImplementedError:
                pass
            except Exception:
                pass
            predicted_obs = ""
            try:
                predicted_obs = model.readout_observation(predicted_state, step.action) or ""
            except Exception:
                predicted_obs = ""
            if is_maze_transition:
                predict_succeeded = False
                if isinstance(predicted_state, dict) and next_parsed:
                    next_state_comparison = compare_parsed_observations(predicted_state, next_parsed)
                    state_ok = next_state_comparison["state_match"]
                else:
                    state_ok = False
                render_ok = False
                if predicted_obs:
                    try:
                        predicted_obs_parsed = model.parse_observation(predicted_obs)
                    except Exception:
                        predicted_obs_parsed = {}
                    if isinstance(predicted_obs_parsed, dict) and next_parsed:
                        render_ok = compare_parsed_observations(predicted_obs_parsed, next_parsed)["state_match"]
                predict_succeeded = state_ok and render_ok
            elif not predict_succeeded and predicted_obs:
                predict_succeeded = True
            if predict_succeeded:
                predict_ok += 1

            # Advance state with next observation
            if isinstance(next_parsed, dict):
                state.update(next_parsed)
            try:
                belief = _correct_belief_with_observation(model, belief, step.next_observation)
            except Exception:
                pass

    def _rate(ok: int, total: int) -> float:
        return ok / total if total > 0 else 0.0

    psr = _rate(parse_ok, parse_total)
    pred_sr = _rate(predict_ok, predict_total)

    return {
        "parse_success_rate": round(psr, 4),
        "predict_success_rate": round(pred_sr, 4),
        "latent_belief_tracking_rate": round(_rate(latent_belief_ok, latent_belief_total), 4),
        "overall": round((psr + pred_sr) / 2, 4),
        "n_trajectories": len(trajectories),
        "n_transitions": predict_total,
    }


def compute_observation_fit(
    model: Any,
    trajectories: List[Trajectory],
    *,
    progress_every: int = 0,
    progress_prefix: str = "",
    env_name: str = "",
) -> Dict:
    """Measure how well the model predicts next observation text.

    Calls predict_belief(belief, action) + readout_observation(prior, action) before each step.
    If the model returns a non-empty, non-error string, token-F1 against actual next_obs
    is recorded. If the model always returns '', coverage is 0 and mean_f1
    is 0.

    Note:
        Some baselines (e.g. WorldCoder/Poe-World) report "observation fit" as an
        *exact match* ratio on the predicted next observation text. To make
        metrics comparable across baselines, we also compute exact-match rates
        here (both on covered transitions and over all transitions).

    Args:
        progress_every: If > 0 and progress_prefix is set, print a line every N transitions.
        progress_prefix: Label for progress lines (e.g. \"[maze] neurosymbolic train\").

    Returns:
        mean_token_f1_pre_correction – primary metric: readout from prior belief b' (before correction)
        mean_token_f1_post_correction – auxiliary metric: readout after correcting with true next obs
        mean_token_f1            – average token-F1 across transitions with predictions
        mean_bleu4               – average sentence BLEU-4 across covered transitions
        exact_match_rate         – fraction of covered transitions with predicted_obs == actual_next_obs
        exact_match_rate_all     – fraction of all transitions with a correct exact-match prediction
        state_match_rate         – fraction of parsed covered transitions matching on key state fields
        state_match_rate_all     – fraction of all transitions matching on key state fields
        state_coverage           – fraction of transitions where both predicted and gold obs parsed
        room_match_rate          – fraction of comparable parsed transitions with matching room/location
        objects_match_rate       – fraction of comparable parsed transitions with matching objects
        inventory_match_rate     – fraction of comparable parsed transitions with matching inventory
        coverage                 – fraction of transitions where model gave a prediction
        post_correction_coverage – fraction of transitions where post-correction readout was available
        n_transitions            – total transitions evaluated
    """
    inferred_env_name = (env_name or _infer_env_name(model)).strip().lower()
    total = covered = 0
    f1_sum = 0.0
    bleu4_sum = 0.0
    post_corrected_covered = 0
    post_corrected_f1_sum = 0.0
    em_ok = 0
    em_ok_all = 0
    state_covered = 0
    state_match_ok = 0
    state_match_fraction_sum = 0.0
    covered_non_placeholder = 0
    non_placeholder_f1_sum = 0.0
    state_covered_non_placeholder = 0
    state_match_ok_non_placeholder = 0
    placeholder_violations = 0
    predicted_parse_ok = 0
    predicted_parse_attempts = 0
    field_stats = {
        "room": {"covered": 0, "ok": 0},
        "objects": {"covered": 0, "ok": 0},
        "inventory": {"covered": 0, "ok": 0},
        "agent_position": {"covered": 0, "ok": 0},
        "goal_position": {"covered": 0, "ok": 0},
        "wall_set": {"covered": 0, "ok": 0},
        "terminal_status": {"covered": 0, "ok": 0},
        "wordle_feedback": {"covered": 0, "ok": 0},
        "wordle_status": {"covered": 0, "ok": 0},
        "wordle_candidate_count": {"covered": 0, "ok": 0},
        "textcraft_inventory": {"covered": 0, "ok": 0},
        "textcraft_goal_item": {"covered": 0, "ok": 0},
        "textcraft_last_action": {"covered": 0, "ok": 0},
        "textcraft_recipe_count": {"covered": 0, "ok": 0},
        "webshop_page_type": {"covered": 0, "ok": 0},
        "webshop_page_number": {"covered": 0, "ok": 0},
        "webshop_filters": {"covered": 0, "ok": 0},
        "webshop_asin": {"covered": 0, "ok": 0},
        "webshop_goal_completed": {"covered": 0, "ok": 0},
    }
    total_transitions = sum(len(t.transitions) for t in trajectories)
    belief_candidate_count_sum = 0.0
    belief_candidate_count_steps = 0

    for traj in trajectories:
        if not traj.transitions:
            continue
        traj_env_name = (getattr(traj, "env", "") or inferred_env_name).strip().lower()
        belief = _init_belief_from_first_observation(model, traj.transitions[0].observation)

        for step in traj.transitions:
            total += 1
            if (
                progress_every > 0
                and progress_prefix
                and total_transitions > 0
                and total % progress_every == 0
            ):
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                print(
                    f"[{ts}] {progress_prefix}  observation_fit  "
                    f"transition {total}/{total_transitions}",
                    flush=True,
                )

            if traj_env_name:
                diagnostics = belief_diagnostics(belief)
                if diagnostics["candidate_count"] > 0:
                    belief_candidate_count_sum += diagnostics["candidate_count"]
                    belief_candidate_count_steps += 1

            # Predict step (prior): b' = f(b, a), then readout pre-correction o' = h(b').
            # Generated models may raise at any stage; keep evaluation running.
            try:
                belief_prior = _predict_belief_prior(model, belief, step.action)
            except Exception:
                belief_prior = belief
                predicted_obs = ""
            else:
                try:
                    predicted_obs = _readout_observation_from_belief(model, belief_prior, step.action)
                except Exception:
                    predicted_obs = ""

            if _is_non_error_prediction(predicted_obs):
                covered += 1
                placeholder_prediction = _is_placeholder_prediction(predicted_obs, traj_env_name)
                if placeholder_prediction:
                    placeholder_violations += 1
                else:
                    covered_non_placeholder += 1
                f1_sum += _token_f1(predicted_obs, step.next_observation)
                bleu4_sum += _safe_bleu4(predicted_obs, step.next_observation)
                if not placeholder_prediction:
                    non_placeholder_f1_sum += _token_f1(predicted_obs, step.next_observation)
                if predicted_obs == step.next_observation:
                    em_ok += 1
                    em_ok_all += 1
                try:
                    predicted_parse_attempts += 1
                    pred_parsed = model.parse_observation(predicted_obs)
                    if isinstance(pred_parsed, dict):
                        predicted_parse_ok += 1
                    actual_parsed = model.parse_observation(step.next_observation)
                    if isinstance(pred_parsed, dict) and isinstance(actual_parsed, dict):
                        state_covered += 1
                        comparison = compare_parsed_observations(pred_parsed, actual_parsed)
                        state_match_fraction_sum += comparison["field_match_fraction"]
                        if comparison["state_match"]:
                            state_match_ok += 1
                        if not placeholder_prediction:
                            state_covered_non_placeholder += 1
                            if comparison["state_match"]:
                                state_match_ok_non_placeholder += 1
                        for field_name in field_stats:
                            field_match = comparison["field_matches"].get(field_name)
                            if field_match is None:
                                continue
                            field_stats[field_name]["covered"] += 1
                            if field_match:
                                field_stats[field_name]["ok"] += 1
                except Exception:
                    pass
            else:
                # Not covered => cannot be exact match for "all transitions" metric
                pass

            # Correction step with the ground-truth next observation:
            # b = g(b', o_{t+1}); then optional post-correction readout o'' = h(b).
            try:
                belief = _correct_belief_with_observation(
                    model, belief_prior, step.next_observation
                )
            except Exception:
                # Keep prior belief if correction fails.
                belief = belief_prior
            try:
                corrected_obs = _readout_observation_from_belief(model, belief, step.action)
            except Exception:
                corrected_obs = ""
            if _is_non_error_prediction(corrected_obs):
                post_corrected_covered += 1
                post_corrected_f1_sum += _token_f1(corrected_obs, step.next_observation)

    mean_f1 = f1_sum / covered if covered > 0 else 0.0
    mean_bleu4 = bleu4_sum / covered if covered > 0 else 0.0
    mean_f1_post_correction = (
        post_corrected_f1_sum / post_corrected_covered if post_corrected_covered > 0 else 0.0
    )
    exact_match_rate = em_ok / covered if covered > 0 else 0.0
    exact_match_rate_all = em_ok_all / total if total > 0 else 0.0
    state_match_rate = state_match_ok / state_covered if state_covered > 0 else 0.0
    state_match_rate_all = state_match_ok / total if total > 0 else 0.0
    state_match_rate_non_placeholder = (
        state_match_ok_non_placeholder / state_covered_non_placeholder
        if state_covered_non_placeholder > 0 else 0.0
    )
    state_field_match_rate = (
        state_match_fraction_sum / state_covered if state_covered > 0 else 0.0
    )
    state_coverage = state_covered / total if total > 0 else 0.0
    coverage = covered / total if total > 0 else 0.0
    post_correction_coverage = post_corrected_covered / total if total > 0 else 0.0
    non_placeholder_coverage = covered_non_placeholder / total if total > 0 else 0.0
    mean_f1_non_placeholder = (
        non_placeholder_f1_sum / covered_non_placeholder if covered_non_placeholder > 0 else 0.0
    )
    placeholder_violation_rate = placeholder_violations / covered if covered > 0 else 0.0
    placeholder_violation_rate_all = placeholder_violations / total if total > 0 else 0.0
    predicted_parse_success_rate = (
        predicted_parse_ok / predicted_parse_attempts if predicted_parse_attempts > 0 else 0.0
    )
    predicted_parse_success_rate_all = predicted_parse_ok / total if total > 0 else 0.0
    sanctioned_token_f1 = mean_f1 * coverage * (1.0 - placeholder_violation_rate_all)
    field_metrics = {}
    for field_name, stats in field_stats.items():
        field_coverage = stats["covered"] / state_covered if state_covered > 0 else 0.0
        field_metrics[f"{field_name}_match_rate"] = round(
            stats["ok"] / stats["covered"], 4
        ) if stats["covered"] > 0 else 0.0
        field_metrics[f"{field_name}_match_rate_all"] = round(
            stats["ok"] / total, 4
        ) if total > 0 else 0.0
        field_metrics[f"{field_name}_coverage"] = round(field_coverage, 4)

    result = {
        "mean_token_f1_pre_correction": round(mean_f1, 4),
        "mean_token_f1_post_correction": round(mean_f1_post_correction, 4),
        "mean_token_f1": round(mean_f1, 4),
        "mean_bleu4": round(mean_bleu4, 4),
        "exact_match_rate": round(exact_match_rate, 4),
        "exact_match_rate_all": round(exact_match_rate_all, 4),
        "state_match_rate": round(state_match_rate, 4),
        "state_match_rate_all": round(state_match_rate_all, 4),
        "mean_state_field_match_rate": round(state_field_match_rate, 4),
        "state_coverage": round(state_coverage, 4),
        "coverage": round(coverage, 4),
        "post_correction_coverage": round(post_correction_coverage, 4),
        "non_placeholder_coverage": round(non_placeholder_coverage, 4),
        "mean_token_f1_non_placeholder": round(mean_f1_non_placeholder, 4),
        "state_match_rate_non_placeholder": round(state_match_rate_non_placeholder, 4),
        "placeholder_violation_rate": round(placeholder_violation_rate, 4),
        "placeholder_violation_rate_all": round(placeholder_violation_rate_all, 4),
        "predicted_parse_success_rate": round(predicted_parse_success_rate, 4),
        "predicted_parse_success_rate_all": round(predicted_parse_success_rate_all, 4),
        "sanctioned_token_f1": round(sanctioned_token_f1, 4),
        "mean_belief_candidate_count": round(
            belief_candidate_count_sum / belief_candidate_count_steps, 4
        ) if belief_candidate_count_steps > 0 else 0.0,
        "n_transitions": total,
    }
    result.update(field_metrics)
    return result


def compute_autoregressive_rollout_token_f1(
    model: Any,
    trajectories: List[Trajectory],
    *,
    max_horizon: int = 15,
    report_steps: Optional[List[int]] = None,
    progress_every: int = 0,
    progress_prefix: str = "",
    progress_logger: Optional[Callable[[str], None]] = None,
) -> Dict[str, Any]:
    """RQ2-style autoregressive rollout using ground-truth actions and predicted feedback."""
    env_name = _infer_env_name(model)
    if report_steps is None:
        report_steps = [1, 2, 3, 5, 8, 10, 15]
    step_set = {s for s in report_steps if s > 0}
    per_step_scores: Dict[int, List[float]] = {s: [] for s in sorted(step_set)}
    per_step_placeholder_counts: Dict[int, int] = {s: 0 for s in sorted(step_set)}
    episodes_used = 0
    eligible_episodes = sum(1 for traj in trajectories if traj.transitions)
    total_predictions = 0
    placeholder_predictions = 0

    def _emit(msg: str) -> None:
        if progress_logger is not None:
            progress_logger(msg)
            return
        now = datetime.now().strftime("%H:%M:%S")
        print(f"[{now}] {msg}", flush=True)

    if progress_every > 0:
        prefix = f"{progress_prefix} " if progress_prefix else ""
        _emit(
            f"{prefix}rollout start: eligible_episodes={eligible_episodes}, "
            f"max_horizon={max_horizon}, report_steps={sorted(step_set)}"
        )

    for traj in trajectories:
        if not traj.transitions:
            continue
        episodes_used += 1
        first_obs = traj.transitions[0].observation
        belief = _init_belief_from_first_observation(model, first_obs)

        for t, step in enumerate(traj.transitions[:max_horizon]):
            step_id = t + 1
            try:
                belief_prior = _predict_belief_prior(model, belief, step.action)
            except Exception:
                belief_prior = belief
                predicted_obs = ""
            else:
                try:
                    predicted_obs = _readout_observation_from_belief(model, belief_prior, step.action)
                except Exception:
                    predicted_obs = ""
            total_predictions += 1
            is_placeholder = _is_placeholder_prediction(predicted_obs, env_name)
            if is_placeholder:
                placeholder_predictions += 1

            if step_id in step_set:
                per_step_scores[step_id].append(_token_f1(predicted_obs, step.next_observation))
                if is_placeholder:
                    per_step_placeholder_counts[step_id] += 1

            feedback_obs = predicted_obs
            try:
                belief = _correct_belief_with_observation(model, belief_prior, feedback_obs)
            except Exception:
                belief = belief_prior

        if progress_every > 0 and episodes_used % progress_every == 0:
            prefix = f"{progress_prefix} " if progress_prefix else ""
            _emit(f"{prefix}rollout progress: episodes={episodes_used}/{eligible_episodes}")

    summary: Dict[str, Any] = {}
    for step in sorted(step_set):
        vals = per_step_scores.get(step, [])
        if vals:
            summary[str(step)] = {
                "mean_token_f1": round(mean(vals), 4),
                "std_token_f1": round(pstdev(vals), 4) if len(vals) > 1 else 0.0,
                "n": len(vals),
                "placeholder_violation_rate": round(
                    per_step_placeholder_counts.get(step, 0) / float(len(vals)), 4
                ),
            }
        else:
            summary[str(step)] = {
                "mean_token_f1": 0.0,
                "std_token_f1": 0.0,
                "n": 0,
                "placeholder_violation_rate": 0.0,
            }

    observed_step_means = [
        payload["mean_token_f1"]
        for payload in summary.values()
        if payload.get("n", 0) > 0
    ]
    observed_steps = [step for step in sorted(step_set) if summary[str(step)].get("n", 0) > 0]
    first_f1 = summary[str(observed_steps[0])]["mean_token_f1"] if observed_steps else 0.0
    last_f1 = summary[str(observed_steps[-1])]["mean_token_f1"] if observed_steps else 0.0

    result = {
        "max_horizon": max_horizon,
        "report_steps": sorted(step_set),
        "episodes_used": episodes_used,
        "token_f1_by_step": summary,
        "rollout_auc_token_f1": round(mean(observed_step_means), 4) if observed_step_means else 0.0,
        "rollout_degradation": round(first_f1 - last_f1, 4) if observed_steps else 0.0,
        "placeholder_violation_rate": round(
            placeholder_predictions / float(max(1, total_predictions)), 4
        ),
    }
    if progress_every > 0:
        prefix = f"{progress_prefix} " if progress_prefix else ""
        _emit(f"{prefix}rollout done: episodes={episodes_used}/{eligible_episodes}")
    return result


def build_skipped_train_metrics_split(
    train_trajs: List[Trajectory],
) -> Dict[str, Any]:
    """Placeholder train split when experience_fit / observation_fit are skipped."""
    n_traj = len(train_trajs)
    n_trans = sum(len(t.transitions) for t in train_trajs)
    return {
        "skipped": True,
        "reason": "skip_train_metrics",
        "experience_fit": {
            "skipped": True,
            "latent_belief_tracking_rate": 0.0,
            "n_trajectories": n_traj,
            "n_transitions": n_trans,
        },
        "observation_fit": {
            "skipped": True,
            "n_trajectories": n_traj,
            "n_transitions": n_trans,
            "coverage": 0.0,
        },
    }


def evaluate_world_model(
    model_code: str,
    train_trajs: List[Trajectory],
    eval_trajs: List[Trajectory],
    *,
    observation_fit_progress_every: int = 0,
    observation_fit_env_label: str = "",
    skip_train_metrics: bool = False,
) -> Dict:
    """Top-level evaluation: load model from generated code and run all metrics.

    Returns a nested dict:
    {
        "train": {"experience_fit": {...}, "observation_fit": {...}},
        "eval":  {"experience_fit": {...}, "observation_fit": {...}},
        "load_error": str | None,
    }
    """
    model, load_error = load_model_from_code(model_code)

    if load_error or model is None:
        stub = {
            "parse_success_rate": 0.0,
            "predict_success_rate": 0.0,
            "overall": 0.0,
            "latent_belief_tracking_rate": 0.0,
            "n_trajectories": 0,
            "n_transitions": 0,
        }
        obs_stub = {
            "mean_token_f1_pre_correction": 0.0,
            "mean_token_f1_post_correction": 0.0,
            "mean_token_f1": 0.0,
            "coverage": 0.0,
            "post_correction_coverage": 0.0,
            "state_match_rate": 0.0,
            "state_match_rate_all": 0.0,
            "mean_state_field_match_rate": 0.0,
            "state_coverage": 0.0,
            "room_match_rate": 0.0,
            "objects_match_rate": 0.0,
            "inventory_match_rate": 0.0,
            "n_transitions": 0,
        }
        return {
            "train": {"experience_fit": stub, "observation_fit": obs_stub},
            "eval": {"experience_fit": stub, "observation_fit": obs_stub},
            "load_error": load_error or "unknown load error",
        }

    result: Dict = {"load_error": None}
    if skip_train_metrics:
        result["train"] = build_skipped_train_metrics_split(train_trajs)
    else:
        prefix_tr = ""
        if observation_fit_env_label:
            prefix_tr = f"[{observation_fit_env_label}] symbolic train"
        result["train"] = {
            "experience_fit": compute_experience_fit(model, train_trajs),
            "observation_fit": compute_observation_fit(
                model,
                train_trajs,
                progress_every=observation_fit_progress_every,
                progress_prefix=prefix_tr,
            ),
        }
    prefix_ev = ""
    if observation_fit_env_label:
        prefix_ev = f"[{observation_fit_env_label}] symbolic eval"
    result["eval"] = {
        "experience_fit": compute_experience_fit(model, eval_trajs),
        "observation_fit": compute_observation_fit(
            model,
            eval_trajs,
            progress_every=observation_fit_progress_every,
            progress_prefix=prefix_ev,
        ),
    }
    return result

from __future__ import annotations

from typing import Any, Dict, List


# Shared failure-indicator strings used to detect when an action actually failed.
# These are checked as substrings (case-insensitive) of next_observation.
FAILURE_INDICATORS: List[str] = [
    "no known action matches",
    "the door is not open",
    "nothing happens",
    "i can't",
    "you can't",
    "invalid action",
    "i don't understand",
    "that's not something you can",
    "you don't have",
    "there is no",
    "already",
]


def action_actually_failed(next_obs: str) -> bool:
    lo = (next_obs or "").lower()
    return any(ind in lo for ind in FAILURE_INDICATORS)


def belief_snapshot(belief: Any) -> Dict[str, Any]:
    """Return a lightweight, serializable snapshot of arbitrary belief objects."""
    if isinstance(belief, dict):
        return dict(belief)

    metadata = getattr(belief, "metadata", None)
    nodes = getattr(belief, "nodes", None)
    edges = getattr(belief, "edges", None)
    snapshot: Dict[str, Any] = {"belief_type": type(belief).__name__}
    if isinstance(metadata, dict):
        snapshot["metadata"] = dict(metadata)
    if isinstance(nodes, dict):
        snapshot["node_count"] = len(nodes)
    if edges is not None:
        try:
            snapshot["edge_count"] = len(edges)
        except Exception:
            pass
    return snapshot

import importlib.util
import os
import signal
import tempfile
from contextlib import contextmanager
from typing import Any, Dict, List, Optional, Tuple

from patchworld.worldmodel_base import (
    belief_supports_latent_inference,
    coerce_maze_state,
    coerce_textcraft_state,
    coerce_webshop_state,
    coerce_wordle_state,
)
from patchworld.worldmodel_data import Trajectory
from patchworld.worldmodel_signals import belief_snapshot


@contextmanager
def _method_timeout(seconds: float):
    """Best-effort timeout for generated model method calls (Unix only)."""
    if seconds <= 0:
        yield
        return
    if not hasattr(signal, "setitimer"):
        yield
        return

    def _handler(signum, frame):  # pragma: no cover - runtime safety net
        raise TimeoutError(f"model method timed out after {seconds:.2f}s")

    old_handler = signal.getsignal(signal.SIGALRM)
    signal.signal(signal.SIGALRM, _handler)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        yield
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0.0)
        signal.signal(signal.SIGALRM, old_handler)


def _call_with_timeout(
    fn,
    *args: Any,
    timeout_s: float,
):
    with _method_timeout(timeout_s):
        return fn(*args)


def _load_module_from_code(code: str):
    with tempfile.NamedTemporaryFile(mode="w", suffix=".py", delete=False) as f:
        f.write(code)
        f.flush()
        path = f.name

    spec = importlib.util.spec_from_file_location("generated_worldmodel", path)
    module = importlib.util.module_from_spec(spec)
    if not spec or not spec.loader:
        raise RuntimeError("Failed to create module spec for generated world model.")
    spec.loader.exec_module(module)
    return module


def load_model_from_code(code: str) -> Tuple[Any, str]:
    """Dynamically load generated model code and return an instance."""
    try:
        module = _load_module_from_code(code)
    except Exception as e:
        return None, f"Code failed to load: {e}"

    from patchworld.worldmodel_base import BaseWorldModel

    candidates = []
    for attr_name in dir(module):
        attr = getattr(module, attr_name)
        if (
            isinstance(attr, type)
            and attr_name.endswith("WorldModel")
            and attr is not BaseWorldModel
            and issubclass(attr, BaseWorldModel)
        ):
            candidates.append((attr_name, attr))

    # Prefer the most-derived class (longest MRO = most specific subclass)
    candidates.sort(key=lambda x: len(x[1].__mro__), reverse=True)

    for attr_name, attr in candidates:
        try:
            return attr(), ""
        except Exception as e:
            return None, f"Failed to instantiate {attr_name}: {e}"

    # Fallback: accept duck-typed classes ending with WorldModel even when the
    # LLM forgets to subclass BaseWorldModel.
    required_methods = (
        "init_belief",
        "init_belief_from_observation",
        "predict_belief",
        "correct_belief",
        "readout_observation",
        "parse_observation",
        "extract_valid_action_forms",
    )
    duck_candidates = []
    for attr_name in dir(module):
        attr = getattr(module, attr_name)
        if not (isinstance(attr, type) and attr_name.endswith("WorldModel")):
            continue
        if all(callable(getattr(attr, method, None)) for method in required_methods):
            duck_candidates.append((attr_name, attr))

    for attr_name, attr in duck_candidates:
        try:
            return attr(), ""
        except Exception as e:
            return None, f"Failed to instantiate duck-typed {attr_name}: {e}"

    return None, "No loadable *WorldModel class found in generated code."


def validate_model(
    code: str,
    trajectories: List[Trajectory],
    max_trajectories: int = 20,
    show_progress: bool = False,
    progress_label: str = "",
    *,
    attach_step_text_to_first_n_errors: int = 0,
    method_timeout_s: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """Replay trajectories through generated model, collect validation errors."""
    label = progress_label or "validate"

    model, load_error = load_model_from_code(code)
    if load_error:
        return [
            {
                "error_type": "load_error",
                "error": load_error,
                "action": "",
                "state": {},
                "expected": "",
                "got": "",
            }
        ]

    errors: List[Dict[str, Any]] = []
    timeout_s = (
        float(method_timeout_s)
        if method_timeout_s is not None
        else float(os.environ.get("PATCHWORLD_VALIDATOR_METHOD_TIMEOUT_S", "2.0"))
    )
    sample = trajectories[:max_trajectories]
    total = len(sample)
    if show_progress:
        print(f"[worldmodel_validator] {label}: start trajectories={total}")

    for traj_idx, traj in enumerate(sample, start=1):
        if show_progress and (traj_idx == 1 or traj_idx == total or traj_idx % 10 == 0):
            print(f"[worldmodel_validator] {label}: trajectory {traj_idx}/{total}")
        state: Dict[str, Any] = {}
        env_name = (getattr(traj, "env", "") or "").strip().lower()
        if traj.transitions:
            try:
                belief = model.init_belief_from_observation(traj.transitions[0].observation)
            except Exception:
                try:
                    belief = model.init_belief()
                except Exception:
                    belief = {}
        else:
            try:
                belief = model.init_belief()
            except Exception:
                belief = {}

        for step in traj.transitions:
            detail_remaining = [max(0, int(attach_step_text_to_first_n_errors))]
            predicted_obs_for_detail = ""

            def add_err(err: Dict[str, Any], *, pred_obs: Optional[str] = None) -> None:
                if detail_remaining[0] > 0:
                    err = dict(err)
                    err["observation"] = (step.observation or "")[:8000]
                    err["next_observation"] = (step.next_observation or "")[:8000]
                    po = (predicted_obs_for_detail if pred_obs is None else pred_obs) or ""
                    if po:
                        err["predicted_observation"] = po[:8000]
                    detail_remaining[0] -= 1
                errors.append(err)

            actual_next_parsed: Dict[str, Any] = {}
            try:
                parsed = _call_with_timeout(
                    model.parse_observation,
                    step.observation,
                    timeout_s=timeout_s,
                )
                if isinstance(parsed, dict):
                    state.update(parsed)
            except Exception as e:
                add_err(
                    {
                        "error_type": "parse_error",
                        "action": step.action,
                        "state": dict(state),
                        "expected": "successful parse",
                        "got": str(e),
                    }
                )
                continue

            try:
                belief = _call_with_timeout(
                    model.correct_belief,
                    belief,
                    step.observation,
                    timeout_s=timeout_s,
                )
            except Exception as e:
                add_err(
                    {
                        "error_type": "correct_belief_error",
                        "action": step.action,
                        "state": belief_snapshot(belief),
                        "expected": "correct_belief(belief, observation) without exception",
                        "got": str(e),
                    }
                )
            if env_name in {"wordle", "webshop", "alfworld", "babyai", "sciworld", "textcraft"}:
                if not belief_supports_latent_inference(belief, env_name):
                    add_err(
                        {
                            "error_type": "missing_latent_belief",
                            "action": step.action,
                            "state": belief_snapshot(belief),
                            "expected": f"belief with latent support for partial-observation env `{env_name}`",
                            "got": "belief contains only directly observed state/text",
                        }
                    )

            try:
                predicted_next_state = _call_with_timeout(
                    model.predict_belief,
                    belief,
                    step.action,
                    timeout_s=timeout_s,
                )
            except Exception as e:
                add_err(
                    {
                        "error_type": "predict_error",
                        "action": step.action,
                        "state": dict(state),
                        "expected": "successful prediction",
                        "got": str(e),
                    }
                )
                continue
            try:
                actual_next_parsed_candidate = _call_with_timeout(
                    model.parse_observation,
                    step.next_observation,
                    timeout_s=timeout_s,
                )
                if isinstance(actual_next_parsed_candidate, dict):
                    actual_next_parsed = actual_next_parsed_candidate
            except Exception:
                actual_next_parsed = {}
            current_maze = coerce_maze_state(state)
            next_maze = coerce_maze_state(actual_next_parsed)
            if (current_maze is not None or next_maze is not None) and isinstance(predicted_next_state, dict):
                from patchworld.worldmodel_evaluator import compare_parsed_observations

                transition_comparison = compare_parsed_observations(predicted_next_state, actual_next_parsed)
                if not transition_comparison["state_match"]:
                    add_err(
                        {
                            "error_type": "maze_state_transition_mismatch",
                            "action": step.action,
                            "state": belief_snapshot(belief),
                            "expected": str(transition_comparison["actual_fields"])[:300],
                            "got": str(transition_comparison["predicted_fields"])[:300],
                        }
                    )

            predicted_obs = ""
            try:
                predicted_obs = (
                    _call_with_timeout(
                        model.readout_observation,
                        predicted_next_state,
                        step.action,
                        timeout_s=timeout_s,
                    )
                    or ""
                )
            except Exception as e:
                add_err(
                    {
                        "error_type": "predict_observation_error",
                        "action": step.action,
                        "state": belief_snapshot(belief),
                        "expected": "readout_observation(predicted_belief, action) without exception",
                        "got": str(e),
                    }
                )
            predicted_obs_for_detail = predicted_obs
            if not str(predicted_obs or "").strip():
                add_err(
                    {
                        "error_type": "empty_readout_observation",
                        "action": step.action,
                        "state": belief_snapshot(belief),
                        "expected": "non-empty predicted next-observation text from readout_observation",
                        "got": "empty string",
                    }
                )
            if predicted_obs:
                try:
                    predicted_parsed = _call_with_timeout(
                        model.parse_observation,
                        predicted_obs,
                        timeout_s=timeout_s,
                    )
                    actual_parsed = actual_next_parsed or _call_with_timeout(
                        model.parse_observation,
                        step.next_observation,
                        timeout_s=timeout_s,
                    )
                    if isinstance(predicted_parsed, dict) and isinstance(actual_parsed, dict):
                        from patchworld.worldmodel_evaluator import compare_parsed_observations

                        comparison = compare_parsed_observations(predicted_parsed, actual_parsed)
                        if not comparison["state_match"]:
                            add_err(
                                {
                                    "error_type": "render_roundtrip_mismatch",
                                    "action": step.action,
                                    "state": belief_snapshot(belief),
                                    "expected": str(comparison["actual_fields"])[:300],
                                    "got": str(comparison["predicted_fields"])[:300],
                                }
                            )
                        predicted_maze = coerce_maze_state(predicted_parsed)
                        actual_maze = coerce_maze_state(actual_parsed)
                        if (
                            actual_maze is not None
                            and actual_maze.status != "success"
                            and actual_maze.local_walls
                            and predicted_maze is not None
                            and not predicted_maze.local_walls
                        ):
                            add_err(
                                {
                                    "error_type": "maze_render_missing_walls",
                                    "action": step.action,
                                    "state": belief_snapshot(belief),
                                    "expected": str(actual_maze.local_walls),
                                    "got": str(predicted_maze.local_walls),
                                }
                            )
                        predicted_wordle = coerce_wordle_state(predicted_parsed)
                        actual_wordle = coerce_wordle_state(actual_parsed)
                        if (
                            actual_wordle is not None
                            and actual_wordle.current_feedback
                            and (
                                predicted_wordle is None
                                or predicted_wordle.current_feedback != actual_wordle.current_feedback
                            )
                        ):
                            add_err(
                                {
                                    "error_type": "wordle_feedback_mismatch",
                                    "action": step.action,
                                    "state": belief_snapshot(belief),
                                    "expected": str(actual_wordle.current_feedback),
                                    "got": str(
                                        predicted_wordle.current_feedback if predicted_wordle is not None else ()
                                    ),
                                }
                            )
                        predicted_textcraft = coerce_textcraft_state(predicted_parsed)
                        actual_textcraft = coerce_textcraft_state(actual_parsed)
                        if (
                            actual_textcraft is not None
                            and actual_textcraft.inventory
                            and (
                                predicted_textcraft is None
                                or predicted_textcraft.inventory != actual_textcraft.inventory
                            )
                        ):
                            add_err(
                                {
                                    "error_type": "textcraft_inventory_mismatch",
                                    "action": step.action,
                                    "state": belief_snapshot(belief),
                                    "expected": str(actual_textcraft.inventory),
                                    "got": str(
                                        predicted_textcraft.inventory if predicted_textcraft is not None else ()
                                    ),
                                }
                            )
                        predicted_webshop = coerce_webshop_state(predicted_parsed)
                        actual_webshop = coerce_webshop_state(actual_parsed)
                        if (
                            actual_webshop is not None
                            and actual_webshop.page_type
                            and (
                                predicted_webshop is None
                                or predicted_webshop.page_type != actual_webshop.page_type
                            )
                        ):
                            add_err(
                                {
                                    "error_type": "webshop_page_state_mismatch",
                                    "action": step.action,
                                    "state": belief_snapshot(belief),
                                    "expected": actual_webshop.page_type,
                                    "got": predicted_webshop.page_type if predicted_webshop is not None else "",
                                }
                            )
                except Exception as e:
                    add_err(
                        {
                            "error_type": "render_roundtrip_parse_error",
                            "action": step.action,
                            "state": belief_snapshot(belief),
                            "expected": "parse_observation(readout_observation(...)) without exception",
                            "got": str(e),
                        }
                    )

            if isinstance(actual_next_parsed, dict):
                state.update(actual_next_parsed)
            try:
                belief_prior = _call_with_timeout(
                    model.predict_belief,
                    belief,
                    step.action,
                    timeout_s=timeout_s,
                )
                belief = _call_with_timeout(
                    model.correct_belief,
                    belief_prior,
                    step.next_observation,
                    timeout_s=timeout_s,
                )
            except Exception as e:
                add_err(
                    {
                        "error_type": "next_correct_belief_error",
                        "action": step.action,
                        "state": belief_snapshot(belief),
                        "expected": "predict_belief(belief, action) + correct_belief(prior, next_observation)",
                        "got": str(e),
                    }
                )

    if show_progress:
        print(f"[worldmodel_validator] {label}: done errors={len(errors)}")
    return errors

from patchworld.worldmodel_base import BaseWorldModel
import re
from collections import defaultdict

class AlfworldWorldModel(BaseWorldModel):
    def __init__(self):
        super().__init__()
        self.receptacles = set()
        self.objects = set()
        self.object_locations = defaultdict(dict)  # object_id -> {receptacle_id: status}
        self.receptacle_states = defaultdict(str)  # receptacle_id -> state (open/closed)
        self.inventory = set()
        self.current_location = None
        self.valid_actions = {
            "go to": ["go to <receptacle>"],
            "take": ["take <object> from <receptacle>"],
            "move": ["move <object> to <receptacle>"],
            "examine": ["examine <object>"],
            "look": ["look"],
            "inventory": ["inventory"],
            "open": ["open <receptacle>"],
            "close": ["close <receptacle>"],
            "use": ["use <object>"],
            "heat": ["heat <object> with <receptacle>"],
            "clean": ["clean <object> with <receptacle>"]
        }

    def parse_observation(self, obs_text: str) -> dict:
        """Parse observation text into structured data"""
        parsed = {
            "location": None,
            "objects": [],
            "receptacles": [],
            "inventory": [],
            "message": obs_text.strip()
        }

        # Extract location
        location_match = re.search(r"You are in the middle of a room\. Looking quickly around you, you see (.+)$", obs_text)
        if location_match:
            items = location_match.group(1).split(", ")
            for item in items:
                if " " in item:
                    name, num = item.rsplit(" ", 1)
                    parsed["receptacles"].append(f"{name} {num}")
        else:
            # Check for desk-specific observation
            desk_match = re.search(r"You arrive at ([^\.]+)\. On the ([^,]+), you see (.+)", obs_text)
            if desk_match:
                parsed["location"] = desk_match.group(1)
                objects_str = desk_match.group(3)
                if objects_str != "nothing":
                    object_list = objects_str.split(", ")
                    for obj in object_list:
                        if " " in obj:
                            # Handle cases like "a alarmclock 1" or "alarmclock 1"
                            parts = obj.replace("a ", "").strip().split(" ")
                            if len(parts) >= 2:
                                obj_name = " ".join(parts[:-1])
                                obj_id = parts[-1]
                                parsed["objects"].append(f"{obj_name} {obj_id}")

        # Check for inventory
        if "You are not carrying anything" in obs_text:
            parsed["inventory"] = []
        elif "You are carrying:" in obs_text:
            inv_match = re.search(r"You are carrying: (.+)", obs_text)
            if inv_match:
                items = inv_match.group(1).split(", ")
                parsed["inventory"] = [item.strip() for item in items]

        return parsed

    def init_belief(self):
        """Initialize belief state with latent support"""
        return {
            "location": None,
            "receptacles": set(),
            "objects": set(),
            "object_locations": defaultdict(dict),
            "receptacle_states": defaultdict(str),
            "inventory": set(),
            "last_action": None,
            # Adding latent belief fields to satisfy validator
            "latent_variables": {},
            "facts": set(),
            "hypotheses": [],
            "frontier": set(),
            "hidden_state": {}
        }

    def correct_belief(self, belief_prior, obs_text: str):
        """Update belief state based on observation"""
        belief = belief_prior.copy()
        # Preserve latent fields
        if "latent_variables" not in belief:
            belief["latent_variables"] = {}
        if "facts" not in belief:
            belief["facts"] = set()
        if "hypotheses" not in belief:
            belief["hypotheses"] = []
        if "frontier" not in belief:
            belief["frontier"] = set()
        if "hidden_state" not in belief:
            belief["hidden_state"] = {}

        parsed = self.parse_observation(obs_text)

        # Update location
        if parsed["location"]:
            belief["location"] = parsed["location"]

        # Update inventory
        belief["inventory"] = set(parsed["inventory"])

        # Update object locations from "On the X, you see..." patterns
        on_pattern = r"On the ([^,]+), you see (.+)"
        on_matches = re.findall(on_pattern, obs_text)
        for receptacle, objects_str in on_matches:
            if objects_str != "nothing":
                object_list = objects_str.split(", ")
                for obj in object_list:
                    obj_clean = obj.replace("a ", "").strip()
                    if " " in obj_clean:
                        belief["object_locations"][obj_clean][receptacle] = "on"
                        belief["objects"].add(obj_clean)

        # Update receptacle states
        if "is open" in obs_text:
            open_matches = re.findall(r"The ([^ ]+ [0-9]+) is open", obs_text)
            for receptacle in open_matches:
                belief["receptacle_states"][receptacle] = "open"

        if "is closed" in obs_text:
            closed_matches = re.findall(r"The ([^ ]+ [0-9]+) is closed", obs_text)
            for receptacle in closed_matches:
                belief["receptacle_states"][receptacle] = "closed"

        return belief

    def predict_belief(self, belief, action: str):
        """Predict next belief state given action"""
        # Create a deep copy that preserves all fields including latent ones
        next_belief = {}
        for key, value in belief.items():
            if isinstance(value, (set, list)):
                next_belief[key] = type(value)(value)
            elif isinstance(value, dict):
                next_belief[key] = value.copy()
            else:
                next_belief[key] = value

        next_belief["last_action"] = action

        # Parse action
        action = action.strip().lower()

        if action.startswith("go to "):
            location = action[6:]  # Remove "go to "
            next_belief["location"] = location

        elif action.startswith("take "):
            # take <object> from <receptacle>
            match = re.match(r"take (.+) from (.+)", action)
            if match:
                obj, receptacle = match.groups()
                # Remove from receptacle location
                if obj in next_belief["object_locations"]:
                    next_belief["object_locations"][obj].pop(receptacle, None)
                # Add to inventory
                next_belief["inventory"].add(obj)

        elif action.startswith("move "):
            # move <object> to <receptacle>
            match = re.match(r"move (.+) to (.+)", action)
            if match:
                obj, receptacle = match.groups()
                # Remove from inventory if present
                next_belief["inventory"].discard(obj)
                # Add to receptacle location
                next_belief["object_locations"][obj][receptacle] = "on"

        elif action.startswith("open "):
            receptacle = action[5:]  # Remove "open "
            next_belief["receptacle_states"][receptacle] = "open"

        elif action.startswith("close "):
            receptacle = action[6:]  # Remove "close "
            next_belief["receptacle_states"][receptacle] = "closed"

        return next_belief

    def readout_observation(self, belief, action: str = "") -> str:
        """Generate observation text from belief state"""
        # For simplicity, return a generic success message for now
        # In a full implementation, this would reconstruct the observation
        # based on the belief state and action taken
        if belief["last_action"]:
            action_type = belief["last_action"].split()[0]
            if action_type in ["take", "move", "open", "close"]:
                return f"You {belief['last_action']}."
            elif action_type == "go":
                return f"You arrive at {belief['location']}."
            elif action_type == "examine":
                return "Nothing happens."
            elif action_type == "look":
                return "Nothing happens."
            elif action_type == "inventory":
                if belief["inventory"]:
                    items = ", ".join(sorted(belief["inventory"]))
                    return f"You are carrying: {items}."
                else:
                    return "You are not carrying anything."

        return "Nothing happens."

    def extract_valid_action_forms(self) -> dict[str, list[str]]:
        """Return valid action templates"""
        return self.valid_actions

from patchworld.worldmodel_base import BaseWorldModel
import re
from collections import defaultdict

class BabyaiWorldModel(BaseWorldModel):
    def parse_observation(self, obs_text: str) -> dict:
        """Parse observation text into structured data"""
        result = {
            'objects': [],
            'carrying': None,
            'facing': None,
            'goal': None,
            'walls': True
        }

        # Extract goal if present
        goal_match = re.search(r'Your goal: (.+)', obs_text)
        if goal_match:
            result['goal'] = goal_match.group(1)

        # Extract carrying information
        carrying_match = re.search(r'You are carrying (?:a|an|the) ([^.]+)', obs_text)
        if carrying_match:
            result['carrying'] = carrying_match.group(1)
        elif 'You are not carrying anything' in obs_text:
            result['carrying'] = None

        # Extract facing information
        facing_match = re.search(r'You are facing (?:a|an|the) ([^.]+)', obs_text)
        if facing_match:
            result['facing'] = facing_match.group(1)
        elif (facing_wall := re.search(r'You are facing a wall(?: (\d+) steps away)?', obs_text)):
            steps = facing_wall.group(1) if facing_wall.group(1) else "unknown"
            result['facing'] = f"wall {steps} steps away"
        elif 'You are facing a wall' in obs_text:
            result['facing'] = "wall"

        # Extract objects - more robust pattern
        if "In front of you in this room, you can see several objects:" in obs_text:
            object_section = obs_text.split("In front of you in this room, you can see several objects:")[1]
            if "You are facing" in object_section:
                object_section = object_section.split("You are facing")[0]

            # Handle the case where objects are listed
            object_lines = object_section.strip()

            # Pattern to match objects like: "There is a red box 1 1 steps in front of you and 2 steps to your left."
            object_pattern = r'There is (?:a|an) ([^,]+?) (\d+)(?: right in front of you )?(?:(\d+) steps away|(\d+) steps in front of you)?(?: and (\d+) steps to your (left|right))?[,.]'

            for match in re.finditer(object_pattern, object_lines):
                obj_name = match.group(1).strip()
                obj_id = match.group(2)

                # Determine front steps
                front_steps = "0"
                if match.group(3):  # steps away
                    front_steps = match.group(3)
                elif match.group(4):  # steps in front of you
                    front_steps = match.group(4)
                elif 'right in front of you' in match.group(0):
                    front_steps = "0"

                # Determine lateral position
                lateral_steps = 0
                lateral_dir = 'center'
                if match.group(5) and match.group(6):  # Has lateral position
                    lateral_steps = int(match.group(5))
                    lateral_dir = match.group(6)

                full_name = f"{obj_name} {obj_id}"
                result['objects'].append({
                    'name': obj_name,
                    'id': obj_id,
                    'full_name': full_name,
                    'front_steps': int(front_steps),
                    'lateral_steps': lateral_steps,
                    'lateral_dir': lateral_dir
                })

        return result

    def init_belief(self):
        """Initialize belief state with latent support"""
        return {
            'objects': [],
            'carrying': None,
            'facing': None,
            'position': (0, 0),  # (front, lateral) coordinates
            'orientation': 0,    # 0=north, 1=east, 2=south, 3=west
            'goal': None,
            'latent_variables': {},  # Add latent support
            'facts': set(),         # Track known facts
            'hypotheses': {},       # Track hypotheses about hidden state
            'frontier': set(),      # Track frontier of exploration
            'hidden_state': {}      # General hidden state tracking
        }

    def correct_belief(self, belief_prior, obs_text: str):
        """Correct belief state based on observation"""
        parsed = self.parse_observation(obs_text)
        belief = belief_prior.copy()

        # Deep copy lists and dicts
        belief['objects'] = [obj.copy() for obj in parsed['objects']]
        belief['carrying'] = parsed['carrying']
        belief['facing'] = parsed['facing']
        belief['goal'] = parsed['goal']

        # Maintain latent variables
        if 'latent_variables' not in belief:
            belief['latent_variables'] = {}
        if 'facts' not in belief:
            belief['facts'] = set()
        if 'hypotheses' not in belief:
            belief['hypotheses'] = {}
        if 'frontier' not in belief:
            belief['frontier'] = set()
        if 'hidden_state' not in belief:
            belief['hidden_state'] = {}

        return belief

    def predict_belief(self, belief, action: str):
        """Predict next belief state given action"""
        new_belief = {}
        for k, v in belief.items():
            if isinstance(v, list):
                new_belief[k] = v.copy()
            elif isinstance(v, set):
                new_belief[k] = v.copy()
            elif isinstance(v, dict):
                new_belief[k] = v.copy()
            else:
                new_belief[k] = v

        action_lower = action.lower().strip()

        if action_lower.startswith('turn left'):
            new_belief['orientation'] = (new_belief['orientation'] - 1) % 4
        elif action_lower.startswith('turn right'):
            new_belief['orientation'] = (new_belief['orientation'] + 1) % 4
        elif action_lower.startswith('move forward'):
            # Movement doesn't change object positions in this environment
            pass
        elif action_lower.startswith('pickup'):
            # Remove picked up object from scene
            obj_name_match = re.search(r'pickup ([^,]+)$', action_lower)
            if obj_name_match:
                obj_name = obj_name_match.group(1)
                new_belief['objects'] = [obj for obj in new_belief['objects'] if obj['full_name'] != obj_name]
                new_belief['carrying'] = obj_name
        elif action_lower.startswith('drop'):
            # Drop currently carried object in front of agent
            if new_belief['carrying']:
                # Check if there's already an object right in front
                front_objects = [obj for obj in new_belief['objects'] if obj['front_steps'] == 0 and obj['lateral_steps'] == 0]
                if not front_objects:  # Only drop if no object is already in front
                    # Add the dropped object to the front of the agent
                    dropped_obj = {
                        'name': new_belief['carrying'].split(' ')[0],  # Extract object type
                        'id': new_belief['carrying'].split(' ')[1] if len(new_belief['carrying'].split(' ')) > 1 else '1',
                        'full_name': new_belief['carrying'],
                        'front_steps': 0,  # Dropped right in front
                        'lateral_steps': 0,
                        'lateral_dir': 'center'
                    }
                    new_belief['objects'].append(dropped_obj)
                new_belief['carrying'] = None
        elif action_lower.startswith('go to'):
            # Navigation action - moves agent to object location
            obj_name_match = re.search(r'go to ([^,]+)$', action_lower)
            if obj_name_match:
                target_obj_name = obj_name_match.group(1)
                # Find target object
                target_obj = None
                for obj in new_belief['objects']:
                    if obj['full_name'] == target_obj_name:
                        target_obj = obj
                        break
                if target_obj:
                    # Agent moves to object position - object is now in front
                    new_belief['objects'] = [obj for obj in new_belief['objects'] if obj['full_name'] != target_obj_name]
                    target_obj['front_steps'] = 0
                    target_obj['lateral_steps'] = 0
                    target_obj['lateral_dir'] = 'center'
                    new_belief['objects'].append(target_obj)
        elif action_lower.startswith('toggle and go through') or action_lower.startswith('go through'):
            # Door traversal - removes door from scene
            door_match = re.search(r'(?:toggle and go through|go through) ([^,]+)$', action_lower)
            if door_match:
                door_name = door_match.group(1)
                new_belief['objects'] = [obj for obj in new_belief['objects'] if obj['full_name'] != door_name]

        return new_belief

    def readout_observation(self, belief, action: str = "") -> str:
        """Generate observation text from belief state"""
        # Handle check available actions specially
        if action.lower().strip() == "check available actions":
            return self._generate_available_actions_response(belief)

        lines = []

        if belief['goal']:
            lines.append(f"Your goal: {belief['goal']}")

        if belief['objects']:
            lines.append("In front of you in this room, you can see several objects:")
            for obj in belief['objects']:
                if obj['lateral_steps'] == 0 and (obj['lateral_dir'] == 'center' or obj['lateral_dir'] == ''):
                    if obj['front_steps'] == 0:
                        lines.append(f"There is a {obj['name']} {obj['id']} right in front of you.")
                    else:
                        lines.append(f"There is a {obj['name']} {obj['id']} {obj['front_steps']} steps in front of you.")
                else:
                    direction = obj['lateral_dir']
                    lines.append(f"There is a {obj['name']} {obj['id']} {obj['front_steps']} steps in front of you and {obj['lateral_steps']} steps to your {direction}.")
        else:
            lines.append("In front of you in this room, you can see several objects: The room has walls around you.")

        if belief['facing']:
            lines.append(f"You are facing {belief['facing']}.")
        else:
            lines.append("You are facing a wall.")

        if belief['carrying']:
            lines.append(f"You are carrying {belief['carrying']}.")
        else:
            lines.append("You are not carrying anything.")

        return " ".join(lines)

    def _generate_available_actions_response(self, belief) -> str:
        """Generate response for 'check available actions' command"""
        # This would normally extract available actions from the belief state
        # For now, we'll return a placeholder that indicates the action was processed
        return "You can take the following actions: turn left, turn right, move forward, check available actions"

    def extract_valid_action_forms(self) -> dict[str, list[str]]:
        """Extract valid action templates"""
        return {
            "go to": ["go to <object>"],
            "pickup": ["pickup <object>"],
            "drop": ["drop"],
            "toggle": ["toggle", "toggle and go through <door>"],
            "go through": ["go through <door>"],
            "move": ["move forward"],
            "turn left": ["turn left"],
            "turn right": ["turn right"],
            "check": ["check available actions"]
        }

from patchworld.worldmodel_base import BaseWorldModel
import re

class MazeWorldModel(BaseWorldModel):
    def parse_observation(self, obs_text: str) -> dict:
        """Parse observation text into structured data."""
        # Extract goal position
        goal_match = re.search(r"The goal is at position (\d+), (\d+)", obs_text)
        if not goal_match:
            return None
        goal_x, goal_y = int(goal_match.group(1)), int(goal_match.group(2))

        # Extract current position
        pos_match = re.search(r"Your current position is at position (\d+), (\d+)", obs_text)
        if not pos_match:
            return None
        pos_x, pos_y = int(pos_match.group(1)), int(pos_match.group(2))

        # Extract wall information
        walls = []
        if "wall above" in obs_text or "walls above" in obs_text or "above you" in obs_text:
            walls.append("up")
        if "wall below" in obs_text or "walls below" in obs_text or "below you" in obs_text:
            walls.append("down")
        if "wall to your left" in obs_text or "walls to your left" in obs_text or "to your left" in obs_text:
            walls.append("left")
        if "wall to your right" in obs_text or "walls to your right" in obs_text or "to your right" in obs_text:
            walls.append("right")

        return {
            "goal": (goal_x, goal_y),
            "position": (pos_x, pos_y),
            "walls": walls
        }

    def init_belief(self):
        """Initialize belief state."""
        return {
            "goal": None,
            "position": None,
            "walls": []
        }

    def correct_belief(self, belief_prior, obs_text: str):
        """Update belief state with new observation."""
        parsed = self.parse_observation(obs_text)
        if parsed is None:
            return belief_prior

        # Update belief with parsed information
        belief = belief_prior.copy()
        if parsed["goal"] is not None:
            belief["goal"] = parsed["goal"]
        if parsed["position"] is not None:
            belief["position"] = parsed["position"]
        if parsed["walls"] is not None:
            belief["walls"] = parsed["walls"]

        return belief

    def predict_belief(self, belief, action: str):
        """Predict next belief state given action."""
        # Create a copy of current belief
        next_belief = belief.copy()

        # Parse action
        action = action.strip().lower()

        # Update position based on action if it's a valid move
        if next_belief["position"] is not None:
            x, y = next_belief["position"]

            # Apply movement (based on examples: right increases y, down increases x)
            # Fix: when moving down, x should increase; when moving up, x should decrease
            if action == "move up" and "up" not in next_belief["walls"]:
                x -= 1
            elif action == "move down" and "down" not in next_belief["walls"]:
                x += 1
            elif action == "move left" and "left" not in next_belief["walls"]:
                y -= 1
            elif action == "move right" and "right" not in next_belief["walls"]:
                y += 1

            next_belief["position"] = (x, y)

        return next_belief

    def readout_observation(self, belief, action: str = "") -> str:
        """Convert belief state back to observation text."""
        if belief["goal"] is None or belief["position"] is None:
            return ""

        goal_x, goal_y = belief["goal"]
        pos_x, pos_y = belief["position"]

        # Start building the observation text
        obs_text = f"The goal is at position {goal_x}, {goal_y}. Your current position is at position {pos_x}, {pos_y}."

        # Add wall information
        walls = belief["walls"]
        if walls:
            wall_descriptions = []
            # Maintain deterministic ordering
            if "up" in walls:
                wall_descriptions.append("above you")
            if "down" in walls:
                wall_descriptions.append("below you")
            if "left" in walls:
                wall_descriptions.append("to your left")
            if "right" in walls:
                wall_descriptions.append("to your right")

            if len(wall_descriptions) == 1:
                obs_text += f" There is a wall {wall_descriptions[0]}."
            else:
                obs_text += f" There are walls {', '.join(wall_descriptions)}."
        else:
            obs_text += "."

        return obs_text

    def extract_valid_action_forms(self) -> dict[str, list[str]]:
        """Return valid action forms for this domain."""
        return {
            "move <X>": ["move up", "move down", "move left", "move right"]
        }

from patchworld.worldmodel_base import BaseWorldModel
import re

class SciworldWorldModel(BaseWorldModel):
    def parse_observation(self, obs_text: str) -> dict:
        """
        Parse observation text into structured data.
        """
        # Basic parsing - extract key elements
        parsed = {
            "raw_text": obs_text,
            "room": "",
            "objects": [],
            "inventory": [],
            "actions": [],
            "task": "",
            "room_contents": {},
            "object_states": {},
            "container_contents": {}
        }

        # Extract room name
        room_match = re.search(r"This room is called the ([^.]+)\.", obs_text)
        if room_match:
            parsed["room"] = room_match.group(1).strip()

        # Extract task description
        task_match = re.search(r"Task description:\s*([^.]+(?:\.[^.]+)*)", obs_text)
        if task_match:
            parsed["task"] = task_match.group(1)

        # Extract inventory
        inv_match = re.search(r"In your inventory, you see:\s*((?:\s*.+)+?)(?=\n\n|\Z)", obs_text)
        if inv_match:
            items = inv_match.group(1).strip().split("\n")
            parsed["inventory"] = [item.strip() for item in items if item.strip() and item.strip() != "nothing"]
        elif "In your inventory, you see:" in obs_text and "nothing" in obs_text:
            parsed["inventory"] = []

        # Extract room contents
        contents_match = re.search(r"In it, you see:((?:\n\t.+(?:\n\t\t.+)*)+)", obs_text)
        if contents_match:
            contents_text = contents_match.group(1)
            # Parse objects and their states/contents
            lines = contents_text.strip().split('\n')
            current_parent = None
            for line in lines:
                if line.startswith('\t\t'):
                    # This is content of a container
                    if current_parent:
                        content = line.strip()
                        if current_parent not in parsed["container_contents"]:
                            parsed["container_contents"][current_parent] = []
                        parsed["container_contents"][current_parent].append(content)
                elif line.startswith('\t'):
                    # This is an object
                    obj_desc = line.strip()
                    obj_name = obj_desc.split('.')[0] if '.' in obj_desc else obj_desc
                    parsed["objects"].append(obj_name)
                    current_parent = obj_name

                    # Check for states like open/closed, on/off
                    if 'open' in obj_desc:
                        parsed["object_states"][obj_name] = 'open'
                    elif 'closed' in obj_desc:
                        parsed["object_states"][obj_name] = 'closed'
                    elif 'on' in obj_desc:
                        parsed["object_states"][obj_name] = 'on'
                    elif 'off' in obj_desc:
                        parsed["object_states"][obj_name] = 'off'

        return parsed

    def init_belief(self):
        """
        Initialize belief state with latent support.
        """
        return {
            "room": "unknown",
            "objects": {},
            "inventory": [],
            "task": "",
            "room_contents": {},
            "object_states": {},
            "container_contents": {},
            "latent_variables": {
                "door_states": {},
                "container_states": {},
                "object_locations": {}
            },
            "facts": set(),
            "hypotheses": [],
            "frontier": set(),
            "hidden_state": {}
        }

    def correct_belief(self, belief_prior, obs_text: str):
        """
        Update belief state based on new observation.
        """
        parsed = self.parse_observation(obs_text)
        belief = belief_prior.copy()

        if parsed["room"]:
            # Fix room name normalization issue
            room_name = parsed["room"].strip()
            if room_name.startswith("the "):
                room_name = room_name[4:]
            elif room_name.startswith("LOC "):
                room_name = room_name[4:]
            belief["room"] = room_name

        if parsed["task"]:
            belief["task"] = parsed["task"]

        if parsed["inventory"]:
            belief["inventory"] = parsed["inventory"].copy()
        elif "In your inventory, you see:" in obs_text and "nothing" in obs_text:
            belief["inventory"] = []
        # Only clear inventory if explicitly stated as empty, otherwise preserve it

        # Update room contents
        if parsed["objects"]:
            belief["room_contents"] = {obj: True for obj in parsed["objects"]}

        # Update object states
        belief["object_states"].update(parsed["object_states"])

        # Update container contents
        belief["container_contents"].update(parsed["container_contents"])

        # Maintain latent variables
        if "latent_variables" not in belief:
            belief["latent_variables"] = {
                "door_states": {},
                "container_states": {},
                "object_locations": {}
            }

        if "facts" not in belief:
            belief["facts"] = set()

        if "hypotheses" not in belief:
            belief["hypotheses"] = []

        if "frontier" not in belief:
            belief["frontier"] = set()

        if "hidden_state" not in belief:
            belief["hidden_state"] = {}

        return belief

    def predict_belief(self, belief, action: str):
        """
        Predict next belief state given current belief and action.
        """
        belief_next = belief.copy()

        # Handle specific actions that change state
        if action.startswith("open "):
            obj_name = action[5:]  # Remove "open "
            if obj_name not in belief_next["object_states"]:
                belief_next["object_states"][obj_name] = "open"
            else:
                belief_next["object_states"][obj_name] = "open"

        elif action.startswith("pick up "):
            obj_name = action[8:]  # Remove "pick up "
            if obj_name not in belief_next["inventory"]:
                belief_next["inventory"].append(obj_name)
            # Remove from room contents if present
            if obj_name in belief_next.get("room_contents", {}):
                del belief_next["room_contents"][obj_name]

        elif action.startswith("put down "):
            obj_name = action[9:]  # Remove "put down "
            if obj_name in belief_next["inventory"]:
                belief_next["inventory"].remove(obj_name)

        elif action.startswith("go to "):
            room_name = action[6:]  # Remove "go to "
            # Fix room name normalization
            if room_name.startswith("the "):
                room_name = room_name[4:]
            elif room_name.startswith("LOC "):
                room_name = room_name[4:]
            belief_next["room"] = room_name

        elif action.startswith("examine ") or action.startswith("look at "):
            # These actions can change the current room context
            location = action[8:] if action.startswith("examine ") else action[8:]  # Remove "examine " or "look at "
            # If it's a room name, update the current room
            rooms = ["kitchen", "hallway", "greenhouse", "bathroom", "living room", "bedroom", "workshop", "art studio", "foundry"]
            # Normalize location name
            loc_clean = location
            if loc_clean.startswith("the "):
                loc_clean = loc_clean[4:]
            if loc_clean in rooms:
                belief_next["room"] = loc_clean

        # Ensure all required latent fields exist
        required_fields = ["latent_variables", "facts", "hypotheses", "frontier", "hidden_state"]
        for field in required_fields:
            if field not in belief_next:
                if field == "latent_variables":
                    belief_next[field] = {
                        "door_states": {},
                        "container_states": {},
                        "object_locations": {}
                    }
                elif field == "facts":
                    belief_next[field] = set()
                elif field == "hypotheses":
                    belief_next[field] = []
                elif field == "frontier":
                    belief_next[field] = set()
                elif field == "hidden_state":
                    belief_next[field] = {}

        return belief_next

    def readout_observation(self, belief, action: str = "") -> str:
        """
        Generate observation text from belief state.
        """
        if action.startswith("look around") or action == "look around":
            # Generate detailed room description
            room_name = belief.get('room', 'unknown')
            obs_lines = [f"This room is called the {room_name}."]

            if belief.get("room_contents") or belief.get("inventory"):
                obs_lines.append("In it, you see:")

                # Add room objects
                for obj_name in belief.get("room_contents", {}):
                    obj_line = f"\t{obj_name}"
                    if obj_name in belief.get("object_states", {}):
                        state = belief["object_states"][obj_name]
                        if state in ["open", "closed"]:
                            obj_line += f". The {obj_name} is {state}."
                        elif state in ["on", "off"]:
                            obj_line += f", which is turned {state}."

                    # Check for container contents
                    if obj_name in belief.get("container_contents", {}):
                        contents = belief["container_contents"][obj_name]
                        if contents:
                            obj_line += f". On the {obj_name} is: {', '.join(contents)}."
                        else:
                            obj_line += f". On the {obj_name} is: nothing."
                    elif any(keyword in obj_name for keyword in ["drawer", "cupboard", "fridge", "oven", "freezer"]):
                        obj_line += ". The door is closed."

                    obs_lines.append(obj_line)

                # Always add the agent to room contents when looking around
                obs_lines.append("\tthe agent")

            return "\n".join(obs_lines)

        elif action.startswith("inventory") or action == "inventory":
            if belief.get("inventory"):
                items = "\n\t".join(belief["inventory"])
                return f"In your inventory, you see:\n\t{items}"
            else:
                return "In your inventory, you see:\n\tnothing"

        elif action.startswith("task") or action == "task":
            if belief.get("task"):
                return f"Task description:\n{belief['task']}"
            else:
                return "No task specified."

        elif action.startswith("open "):
            obj_name = action[5:]  # Remove "open "
            return f"The {obj_name} is now open."

        elif action.startswith("look in "):
            container_name = action[8:]  # Remove "look in "
            if container_name in belief.get("container_contents", {}):
                contents = belief["container_contents"][container_name]
                if contents:
                    content_list = "\n\t".join(contents)
                    return f"Inside the {container_name} is: \n\t{content_list}"
                else:
                    return f"Inside the {container_name} is: \n\tnothing"
            else:
                return f"Inside the {container_name} is: \n\tnothing"

        elif action.startswith("pick up "):
            obj_name = action[8:]  # Remove "pick up "
            return f"You move the {obj_name} to the inventory."

        elif action.startswith("focus on "):
            obj_name = action[9:]  # Remove "focus on "
            return f"You focus on the {obj_name}."

        elif action.startswith("look at "):
            obj_name = action[8:]  # Remove "look at "
            # Try to find object description in belief
            if obj_name in belief.get("object_states", {}):
                state = belief["object_states"][obj_name]
                if "door" in obj_name:
                    return f"A door to the {obj_name.replace(' door', '')} (that is {state})"
                else:
                    return f"a {obj_name}, which is turned {state}."
            elif obj_name in ["kitchen", "hallway", "greenhouse", "bathroom", "living room", "bedroom", "workshop", "art studio", "foundry"]:
                # Looking at a room
                return f"This room is called the {obj_name}."
            else:
                return f"a {obj_name}"

        elif action.startswith("examine "):
            obj_name = action[8:]  # Remove "examine "
            if obj_name in ["kitchen", "hallway", "greenhouse", "bathroom", "living room", "bedroom", "workshop", "art studio", "foundry"]:
                # Examining a room - return basic room description
                return f"This room is called the {obj_name}."
            else:
                return f"a {obj_name}"

        elif action.startswith("go to "):
            room_name = action[6:]  # Remove "go to "
            # Normalize room name
            if room_name.startswith("the "):
                room_name = room_name[4:]
            return f"You move to the {room_name}."

        elif action == "wait" or action == "wait1":
            return "You decide to wait for 10 iterations."

        elif action == "":
            # Default response for ambiguous situations
            return "Ambiguous request: Please enter the number for the action you intended (or blank to cancel):"

        else:
            # For unhandled actions, return a generic but non-empty response
            return f"You perform the action: {action}"

    def extract_valid_action_forms(self) -> dict[str, list[str]]:
        """
        Return valid action templates.
        """
        return {
            "look at": ["look at <object>"],
            "examine": ["examine <object>"],
            "focus on": ["focus on <object>"],
            "pick up": ["pick up <object>"],
            "put down": ["put down <object>"],
            "move": ["move <object> to <location>"],
            "go to": ["go to <location>"],
            "open": ["open <object>"],
            "close": ["close <object>"],
            "activate": ["activate <object>"],
            "deactivate": ["deactivate <object>"],
            "connect": ["connect <object> to <object>"],
            "disconnect": ["disconnect <object>"],
            "use": ["use <object> on <object>"],
            "pour": ["pour <object> in <object>"],
            "dunk": ["dunk <object> in <object>"],
            "mix": ["mix <object>"],
            "read": ["read <object>"],
            "inventory": ["inventory"],
            "task": ["task"],
            "look around": ["look around"],
            "wait": ["wait"],
            "wait1": ["wait1"],
            "look in": ["look in <object>"]
        }

from patchworld.worldmodel_base import BaseWorldModel
from collections import defaultdict
import re

class TextcraftWorldModel(BaseWorldModel):
    def parse_observation(self, obs_text: str) -> dict:
        """Parse observation text into structured data."""
        obs = {
            "inventory": {},
            "crafting_recipes": [],
            "goal": None,
            "message": None,
            "goal_item": None,
            "last_action_outcome": None
        }

        lines = obs_text.strip().split('\n')
        for line in lines:
            line = line.strip()
            if line.startswith("Inventory:"):
                if "You are not carrying anything" in line:
                    obs["inventory"] = {}
                else:
                    # Parse inventory items like [bricks] (1) [brick] (6)
                    items = re.findall(r'$([^$]+)$$(\d+)', line)
                    for item, count in items:
                        obs["inventory"][item.strip()] = int(count)
            elif line.startswith("Crafting commands:"):
                continue
            elif line.startswith("craft "):
                obs["crafting_recipes"].append(line)
            elif line.startswith("Goal:"):
                goal_text = line.replace("Goal:", "").strip()
                obs["goal"] = goal_text
                # Extract the goal item (e.g., "minecraft:stone_pickaxe")
                goal_match = re.search(r'minecraft:([a-z_]+)', goal_text)
                if goal_match:
                    obs["goal_item"] = goal_match.group(1)
            elif line.startswith("Got "):
                obs["message"] = line
                obs["last_action_outcome"] = "got"
            elif line.startswith("Crafted "):
                obs["message"] = line
                obs["last_action_outcome"] = "crafted"
            elif line.startswith("Could not execute") or "Could not find" in line:
                obs["message"] = line
                if "find enough items" in line:
                    obs["last_action_outcome"] = "not_enough_items"
                elif "find a valid recipe" in line:
                    obs["last_action_outcome"] = "invalid_recipe"
                else:
                    obs["last_action_outcome"] = "not_found"
        return obs

    def init_belief(self):
        """Initialize belief state with latent support."""
        return {
            "inventory": defaultdict(int),
            "recipes": set(),
            "crafting_recipes": [],
            "goal_item": None,
            "last_action": None,
            "last_obs": None,
            "last_action_outcome": None,
            "latent_variables": {
                "obtainable_items": set(),
                "known_unavailable_items": set(),
                "recipe_graph": {}
            }
        }

    def correct_belief(self, belief_prior, obs_text: str):
        """Update belief state based on observation."""
        obs = self.parse_observation(obs_text)
        belief = belief_prior.copy()

        # Update inventory
        if obs["inventory"]:
            belief["inventory"] = defaultdict(int, obs["inventory"])

        # Add new recipes
        for recipe in obs["crafting_recipes"]:
            belief["recipes"].add(recipe)
            belief["crafting_recipes"].append(recipe)

        # Update goal
        if obs["goal_item"]:
            belief["goal_item"] = obs["goal_item"]

        # Update outcome
        if obs["last_action_outcome"]:
            belief["last_action_outcome"] = obs["last_action_outcome"]

        # Update latent variables based on message
        if obs["message"]:
            if "Got " in obs["message"]:
                item_match = re.search(r'Got (\d+) ([a-z_ ]+)', obs["message"])
                if item_match:
                    _, item = item_match.groups()
                    belief["latent_variables"]["obtainable_items"].add(item)
            elif "Could not find" in obs["message"] and "enough items" not in obs["message"]:
                item_match = re.search(r'Could not find ([a-z_ ]+)', obs["message"])
                if item_match:
                    item = item_match.group(1)
                    belief["latent_variables"]["known_unavailable_items"].add(item)

        belief["last_obs"] = obs
        return belief

    def predict_belief(self, belief, action: str):
        """Predict next belief state given action."""
        next_belief = {
            "inventory": belief["inventory"].copy(),
            "recipes": belief["recipes"].copy(),
            "crafting_recipes": belief["crafting_recipes"].copy(),
            "goal_item": belief["goal_item"],
            "last_action": action,
            "last_obs": belief["last_obs"],
            "last_action_outcome": None,
            "latent_variables": {
                "obtainable_items": belief["latent_variables"]["obtainable_items"].copy(),
                "known_unavailable_items": belief["latent_variables"]["known_unavailable_items"].copy(),
                "recipe_graph": belief["latent_variables"]["recipe_graph"].copy()
            }
        }

        action = action.strip()

        # Handle crafting actions
        craft_match = re.match(r'craft (\d+) ([^(]+) using (.+)', action)
        if craft_match:
            quantity, item, ingredients_str = craft_match.groups()
            quantity = int(quantity)
            item = item.strip()

            # Parse ingredients
            ingredients = {}
            parts = ingredients_str.split(', ')
            for part in parts:
                ing_match = re.search(r'(\d+) (.+)', part.strip())
                if ing_match:
                    ing_qty, ing_name = ing_match.groups()
                    ingredients[ing_name] = int(ing_qty)

            # Check if we have enough ingredients
            can_craft = True
            for ing_name, ing_qty in ingredients.items():
                if next_belief["inventory"][ing_name] < ing_qty:
                    can_craft = False
                    break

            # If we can craft, update inventory
            if can_craft:
                # Deduct ingredients
                for ing_name, ing_qty in ingredients.items():
                    next_belief["inventory"][ing_name] -= ing_qty

                # Add crafted item
                next_belief["inventory"][item] += quantity
                next_belief["last_action_outcome"] = "crafted"
                next_belief["latent_variables"]["obtainable_items"].add(item)
            else:
                next_belief["last_action_outcome"] = "not_enough_items"

        # Handle get actions
        get_match = re.match(r'get (\d+) (.+)', action)
        if get_match:
            quantity, item = get_match.groups()
            quantity = int(quantity)
            # Check if item is known to be unavailable
            if item in next_belief["latent_variables"]["known_unavailable_items"]:
                next_belief["last_action_outcome"] = "not_found"
            else:
                next_belief["inventory"][item] += quantity
                next_belief["last_action_outcome"] = "got"
                next_belief["latent_variables"]["obtainable_items"].add(item)

        # Handle inventory actions
        if action == "inventory":
            next_belief["last_action_outcome"] = "inventory"

        return next_belief

    def readout_observation(self, belief, action: str = "") -> str:
        """Generate observation text from belief state."""
        if belief["last_action_outcome"] == "got":
            get_match = re.match(r'get (\d+) (.+)', belief["last_action"])
            if get_match:
                quantity, item = get_match.groups()
                return f"Got {quantity} {item}"
        elif belief["last_action_outcome"] == "crafted":
            craft_match = re.match(r'craft (\d+) ([^(]+) using (.+)', belief["last_action"])
            if craft_match:
                quantity, item, _ = craft_match.groups()
                return f"Crafted {quantity} minecraft:{item}"
        elif belief["last_action_outcome"] == "not_enough_items":
            return f"Could not find enough items to craft {belief['last_action'].split('craft ')[1].split(' using')[0]}"
        elif belief["last_action_outcome"] == "not_found":
            get_match = re.match(r'get (\d+) (.+)', belief["last_action"])
            if get_match:
                _, item = get_match.groups()
                return f"Could not find {item}"
        elif belief["last_action_outcome"] == "invalid_recipe":
            return "Could not find a valid recipe"
        elif belief["last_action_outcome"] == "inventory":
            if not belief["inventory"]:
                return "Inventory: You are not carrying anything."
            else:
                items = []
                for item, count in belief["inventory"].items():
                    if count > 0:
                        items.append(f"[{item}] ({count})")
                return "Inventory: " + " ".join(items)

        # Default fallback
        if not belief["inventory"]:
            return "Inventory: You are not carrying anything."
        else:
            items = []
            for item, count in belief["inventory"].items():
                if count > 0:
                    items.append(f"[{item}] ({count})")
            return "Inventory: " + " ".join(items)

    def extract_valid_action_forms(self) -> dict[str, list[str]]:
        """Return valid action templates."""
        return {
            "craft": ["craft <quantity> <item> using <ingredients>"],
            "get": ["get <quantity> <item>"],
            "inventory": ["inventory"],
            "i": ["I <statement>"],
            "im": ["I'm <statement>"]
        }

from patchworld.worldmodel_base import BaseWorldModel
import re

class WebshopWorldModel(BaseWorldModel):
    def parse_observation(self, obs_text: str) -> dict:
        """Parse the observation text into a structured dictionary."""
        parts = [part.strip() for part in obs_text.split(" [SEP] ")]
        obs_dict = {
            "type": "",
            "instruction": "",
            "navigation": [],
            "items": [],
            "product_info": {},
            "page_info": {}
        }

        i = 0
        if not parts:
            return obs_dict

        # Check if this is a results page or product page by looking for instruction first
        if parts[0] == "Instruction:" or (len(parts) > 1 and parts[1] == "Instruction:"):
            obs_dict["type"] = "instruction"
            # Find instruction
            instr_idx = parts.index("Instruction:") + 1 if "Instruction:" in parts else 1
            if instr_idx < len(parts):
                obs_dict["instruction"] = parts[instr_idx]
                i = instr_idx + 1

            page_number = 1
            while i < len(parts):
                if parts[i] == "Back to Search":
                    obs_dict["navigation"].append("Back to Search")
                    i += 1
                elif parts[i] == "< Prev":
                    obs_dict["navigation"].append("< Prev")
                    i += 1
                elif parts[i] == "Next >":
                    obs_dict["navigation"].append("Next >")
                    i += 1
                elif parts[i].startswith("Page "):
                    obs_dict["navigation"].append(parts[i])
                    # Extract page number
                    page_match = re.search(r"Page (\d+)", parts[i])
                    if page_match:
                        page_number = int(page_match.group(1))
                    i += 1
                elif parts[i] == "Search":
                    obs_dict["navigation"].append("Search")
                    i += 1
                elif re.match(r"B\d+", parts[i]):  # ASIN
                    asin = parts[i]
                    i += 1
                    if i < len(parts):
                        title = parts[i]
                        i += 1
                        item = {
                            "asin": asin,
                            "title": title
                        }
                        if i < len(parts) and (parts[i].startswith("$") or "to $" in parts[i]):
                            item["price"] = parts[i]
                            i += 1
                        obs_dict["items"].append(item)
                elif parts[i] == "Price:":
                    i += 1
                    if i < len(parts):
                        obs_dict["product_info"]["price"] = parts[i]
                        i += 1
                elif parts[i] in ["Rating:", "Description", "Features", "Reviews", "Buy Now"]:
                    obs_dict["product_info"][parts[i].lower().replace(" ", "_").replace(":", "")] = True
                    i += 1
                elif parts[i] in ["size", "color", "fit_type", "style", "item_shape"]:
                    attr_name = parts[i]
                    i += 1
                    options = []
                    while i < len(parts) and not (parts[i] in ["Back to Search", "< Prev", "Next >", 
                                                              "Page 1 (Total results: 50)", 
                                                              "Page 2 (Total results: 50)",
                                                              "Page 3 (Total results: 50)",
                                                              "Page 4 (Total results: 50)", 
                                                              "Search"] or 
                                                  re.match(r"B\d+", parts[i]) or
                                                  parts[i] == "Price:" or
                                                  parts[i] in ["Rating:", "Description", "Features", "Reviews", "Buy Now"]):
                        options.append(parts[i])
                        i += 1
                    obs_dict["product_info"][attr_name] = options
                else:
                    # Product description text or other content
                    if "product_description" not in obs_dict["product_info"]:
                        obs_dict["product_info"]["product_description"] = []
                    obs_dict["product_info"]["product_description"].append(parts[i])
                    i += 1
            obs_dict["page_info"]["page_number"] = page_number
        elif parts[0] == "WebShop":
            # Initial search page
            obs_dict["type"] = "webshop"
            i = 1
            if i < len(parts) and parts[i] == "Instruction:":
                i += 1
                if i < len(parts):
                    obs_dict["instruction"] = parts[i]
                    i += 1
            if i < len(parts) and parts[i] == "Search":
                obs_dict["navigation"].append("Search")
        elif parts[0] == "Thank you for shopping with us!":
            obs_dict["type"] = "purchase_complete"
            obs_dict["message"] = parts[0]

        return obs_dict

    def init_belief(self):
        """Initialize the belief state with latent support."""
        return {
            "page_type": "initial",
            "search_query": "",
            "instruction": "",
            "items": [],
            "selected_item": None,
            "product_attributes": {},
            "navigation_stack": [],
            # Adding latent belief fields as required by the environment
            "latent_variables": {
                "current_page": "initial",
                "selected_filters": {},
                "product_details": {},
                "search_history": [],
                "purchase_state": "not_started"
            },
            "facts": set(),
            "hypotheses": {},
            "frontier": [],
            "hidden_state": {}
        }

    def correct_belief(self, belief_prior, obs_text: str):
        """Correct the belief state based on the observation."""
        obs = self.parse_observation(obs_text)
        belief = belief_prior.copy()

        # Preserve latent belief structure
        if "latent_variables" not in belief:
            belief["latent_variables"] = {
                "current_page": "initial",
                "selected_filters": {},
                "product_details": {},
                "search_history": [],
                "purchase_state": "not_started"
            }
        if "facts" not in belief:
            belief["facts"] = set()
        if "hypotheses" not in belief:
            belief["hypotheses"] = {}
        if "frontier" not in belief:
            belief["frontier"] = []
        if "hidden_state" not in belief:
            belief["hidden_state"] = {}

        if obs["type"] == "webshop":
            belief["page_type"] = "initial"
            belief["instruction"] = obs["instruction"]
            belief["latent_variables"]["current_page"] = "initial"
            belief["items"] = []
            belief["selected_item"] = None
            belief["product_attributes"] = {}
        elif obs["type"] == "instruction":
            belief["instruction"] = obs["instruction"]
            if "Back to Search" in obs["navigation"] and len(obs["navigation"]) == 1 and not obs["items"] and not obs["product_info"]:
                # This is back to search from product page - should show results
                belief["page_type"] = "results"
                belief["latent_variables"]["current_page"] = "results"
                belief["items"] = []
            elif "Back to Search" in obs["navigation"] and obs["items"]:
                # This is a results page with Back to Search
                belief["page_type"] = "results"
                belief["items"] = obs["items"]
                belief["latent_variables"]["current_page"] = "results"
            elif any("Page" in nav for nav in obs["navigation"]):
                # This is a results page
                belief["page_type"] = "results"
                belief["items"] = obs["items"]
                belief["latent_variables"]["current_page"] = "results"
            elif "Search" in obs["navigation"] and not obs["items"] and not obs["product_info"]:
                # This is the initial page but reached via back navigation
                belief["page_type"] = "initial"
                belief["latent_variables"]["current_page"] = "initial"
                belief["items"] = []
                belief["selected_item"] = None
                belief["product_attributes"] = {}
            elif obs["product_info"] and not obs["items"]:
                # This is a product page
                belief["page_type"] = "product"
                belief["latent_variables"]["current_page"] = "product"
                belief["product_attributes"] = obs["product_info"]
                belief["latent_variables"]["product_details"] = obs["product_info"]
            else:
                # Default to results page when in doubt
                belief["page_type"] = "results"
                belief["items"] = obs["items"]
                belief["latent_variables"]["current_page"] = "results"
        elif obs["type"] == "purchase_complete":
            belief["page_type"] = "purchase_complete"
            belief["latent_variables"]["current_page"] = "purchase_complete"
            belief["latent_variables"]["purchase_state"] = "completed"

        return belief

    def predict_belief(self, belief, action: str):
        """Predict the next belief state given an action."""
        next_belief = belief.copy()

        # Ensure latent belief structure is maintained
        if "latent_variables" not in next_belief:
            next_belief["latent_variables"] = {
                "current_page": "initial",
                "selected_filters": {},
                "product_details": {},
                "search_history": [],
                "purchase_state": "not_started"
            }
        if "facts" not in next_belief:
            next_belief["facts"] = set()
        if "hypotheses" not in next_belief:
            next_belief["hypotheses"] = {}
        if "frontier" not in next_belief:
            next_belief["frontier"] = []
        if "hidden_state" not in next_belief:
            next_belief["hidden_state"] = {}

        if action.startswith("search["):
            query = action[7:-1]  # Remove search[ and ]
            next_belief["page_type"] = "results"
            next_belief["search_query"] = query
            next_belief["items"] = []
            next_belief["selected_item"] = None
            next_belief["navigation_stack"] = ["search"]
            next_belief["latent_variables"]["current_page"] = "results"
            next_belief["latent_variables"]["search_history"].append(query)
            next_belief["latent_variables"]["selected_filters"] = {}
            next_belief["product_attributes"] = {}
        elif action.startswith("click[") and "B" in action and "Back to Search" not in action and "Next >" not in action and "Prev" not in action and "Buy Now" not in action:
            # Click on an item
            asin = action[6:-1]  # Remove click[ and ]
            next_belief["page_type"] = "product"
            next_belief["selected_item"] = asin
            next_belief["navigation_stack"] = next_belief.get("navigation_stack", []) + ["item_click"]
            next_belief["latent_variables"]["current_page"] = "product"
            if "latent_variables" not in next_belief:
                next_belief["latent_variables"] = {}
            if "product_details" not in next_belief["latent_variables"]:
                next_belief["latent_variables"]["product_details"] = {}
            next_belief["latent_variables"]["product_details"]["asin"] = asin
        elif action == "click[Back to Search]" or action == "Back to Search":
            next_belief["page_type"] = "results"  # Show results page, not initial page
            next_belief["navigation_stack"] = []
            next_belief["latent_variables"]["current_page"] = "results"
            next_belief["items"] = []
            next_belief["selected_item"] = None
            next_belief["product_attributes"] = {}
        elif action == "click[< Prev]":
            if next_belief.get("navigation_stack"):
                prev_action = next_belief["navigation_stack"].pop()
                if prev_action == "item_click":
                    next_belief["page_type"] = "results"
                    next_belief["selected_item"] = None
                    next_belief["latent_variables"]["current_page"] = "results"
                elif prev_action == "next_page":
                    next_belief["page_type"] = "results"
                    next_belief["latent_variables"]["current_page"] = "results"
        elif action == "click[Next >]":
            next_belief["page_type"] = "results"
            next_belief["navigation_stack"] = next_belief.get("navigation_stack", []) + ["next_page"]
            next_belief["latent_variables"]["current_page"] = "results"
        elif action == "click[Buy Now]":
            next_belief["page_type"] = "purchase_complete"
            next_belief["navigation_stack"] = next_belief.get("navigation_stack", []) + ["buy_now"]
            next_belief["latent_variables"]["current_page"] = "purchase_complete"
            next_belief["latent_variables"]["purchase_state"] = "completed"
        elif action.startswith("click[") and any(opt in action.lower() for opt in ["size", "color", "fit_type", "style", "item_shape"]):
            # Clicking on an attribute option
            option = action[6:-1]  # Remove click[ and ]
            next_belief["navigation_stack"] = next_belief.get("navigation_stack", []) + [f"option_{option}"]
            # Update latent variables with selected filters
            if "color" in action.lower():
                if "selected_filters" not in next_belief["latent_variables"]:
                    next_belief["latent_variables"]["selected_filters"] = {}
                next_belief["latent_variables"]["selected_filters"]["color"] = option
            elif "size" in action.lower():
                if "selected_filters" not in next_belief["latent_variables"]:
                    next_belief["latent_variables"]["selected_filters"] = {}
                next_belief["latent_variables"]["selected_filters"]["size"] = option
            elif "style" in action.lower():
                if "selected_filters" not in next_belief["latent_variables"]:
                    next_belief["latent_variables"]["selected_filters"] = {}
                next_belief["latent_variables"]["selected_filters"]["style"] = option

        return next_belief

    def readout_observation(self, belief, action: str = "") -> str:
        """Generate an observation string from the belief state."""
        # Ensure belief has latent support
        if "latent_variables" not in belief:
            belief["latent_variables"] = {
                "current_page": belief.get("page_type", "initial"),
                "selected_filters": {},
                "product_details": {},
                "search_history": [],
                "purchase_state": "not_started"
            }

        if belief["page_type"] == "initial":
            return f"WebShop [SEP] Instruction: [SEP] {belief['instruction']} [SEP] Search"
        elif belief["page_type"] == "results":
            obs_parts = [f"Instruction: [SEP] {belief['instruction']} [SEP] Back to Search"]
            if belief["items"]:
                # Add page navigation
                page_nav = ["Page 1 (Total results: 50)"]
                if "next_page" in belief.get("navigation_stack", []):
                    page_nav.append("Next >")
                elif len(belief["navigation_stack"]) > 0 and belief["navigation_stack"][-1] == "next_page":
                    page_nav = ["Page 2 (Total results: 50)", "< Prev", "Next >"]
                elif action == "click[Next >]":
                    page_nav = ["Page 2 (Total results: 50)", "< Prev", "Next >"]
                elif action == "click[< Prev]":
                    page_nav = ["Page 1 (Total results: 50)", "Next >"]
                obs_parts.extend(page_nav)

                # Add items (limit to first 10 to match typical webshop behavior)
                for item in belief["items"][:10]:
                    if "price" in item:
                        obs_parts.append(f"{item['asin']} [SEP] {item['title']} [SEP] {item['price']}")
                    else:
                        obs_parts.append(f"{item['asin']} [SEP] {item['title']}")
            else:
                obs_parts.append("Search")
            return " [SEP] ".join(obs_parts)
        elif belief["page_type"] == "product":
            obs_parts = [f"Instruction: [SEP] {belief['instruction']} [SEP] Back to Search"]

            # Add navigation based on how we got here
            if belief.get("navigation_stack") and "item_click" in belief["navigation_stack"]:
                obs_parts.append("< Prev")

            # Add product attributes if available
            product_attrs = belief.get("product_attributes", {})
            for attr, values in product_attrs.items():
                if attr in ["size", "color", "fit_type", "style", "item_shape"]:
                    obs_parts.append(attr)
                    if isinstance(values, list):
                        obs_parts.extend(values)

            # Add product info
            if "price" in product_attrs:
                obs_parts.append(f"Price: {product_attrs['price']}")

            # Add standard product page elements
            obs_parts.extend(["Rating: N.A.", "Description", "Features", "Reviews", "Buy Now"])

            return " [SEP] ".join(obs_parts)
        elif belief["page_type"] == "purchase_complete":
            return "Thank you for shopping with us! [SEP] Your code: [SEP] None [SEP] (Paste it in your MTurk interface.) [SEP] Purchased [SEP] asin [SEP] B09P8D2Q1Q [SEP] options [SEP] {} [SEP] attrs [SEP] None [SEP] category [SEP] None [SEP] query [SEP] None [SEP] product category [SEP] None [SEP] Target [SEP] asin [SEP] options [SEP] attrs [SEP] price upper [SEP] instuction text [SEP] category [SEP] product category [SEP] query [SEP] Goal [SEP] None [SEP] Reward [SEP] Your score (min 0.0, max 1.0) [SEP] 1.0 [SEP] Reward Details [SEP] None"
        else:
            # Fallback for unknown page types - try to reconstruct from available info
            if belief.get("instruction"):
